quests[48376] = { id = 48376, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urobliterum in Massen", progress = "Oho, was habt Ihr denn da? Ursargerit? Klingt ja ganz schön edel!\n\nWenn wir etwas von dem Zeugs mit Obliterum mischen, bekommt es noch mehr Bumms! Und wenn Ihr das dann auf Eure Rüstung auftragt - aber hoppla!\n\nIch wette, wenn wir einen ganzen Haufen von dem Zeug auf einmal zusammenschmeißen, kriegen wir eine ganze Wagenladung fertig! Und, woll'n wir's mal probieren?", completion = "<Nachdem Caelen den Stapel Sargerit mit dem Stapel Obliterum bei der Schmiede verbunden hat, geht von der Legierung eine recht beeindruckende Macht aus.>\n\nDa habt Ihr es, Söhnchen. Ob das Zeug wohl giftig ist? Bestimmt nicht, oder?" }
quests[48386] = { id = 48386, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jed'hinturnier" }
quests[48395] = { id = 48395, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flüstern aus den Schatten", description = "<Held/Heldin>, wir haben ein Problem.\n\nDer uralte Kult der Nekrodunklen ist zurück.\n\nAls Dargrul noch Unterkönig war, hat er diese Kultisten sofort niedergeschlagen, sobald sie sich irgendwo zeigten, und hat so verhindert, dass sie Neltharions Hort erkundeten.\n\nAber nun, da Dargrul fort ist, stürmen sie das Gewölbe in Massen.\n\nWir müssen sie aufhalten, bevor sie finden, wonach sie suchen.", sourceObjective = "Helft Navarrogg dabei, die Nekrodunklen zu besiegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[48399] = { id = 48399, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkle (Eisen-)Flut", description = "Diese roten Augen... flammende Bärte... dunkle, staubige Haut. Das können nur Dunkeleisenzwerge sein. Ich habe nie zuvor einen gesehen.\n\nIch vermute, dass sie im Auftrag der Allianz hierher entsandt wurden. Der Treueschwur meines Volks bindet mich an die Horde und wir sollten unsere Loyalität hier unmissverständlich unter Beweis stellen.\n\nTod den Dunkeleisenzwergen! Sorgt dafür, dass sie keinen weiteren Millimeter von diesem Strand einnehmen.", sourceObjective = "Tötet 7 Dunkeleisenzwerge.", completion = "Wir müssen eindeutig zeigen, auf wessen Seite wir stehen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[48400] = { id = 48400, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Telemantischer Coup", description = "Wir dürfen ihnen das Auge nicht überlassen, {name}.\n\nGlücklicherweise bin ich nicht nur Archäologe, sondern auch Telemant. Großtelemant Oculeth selbst hat die Frau unterrichtet, die meinen Meister ausgebildet hat. Mithilfe dieser Kunst kann ich das Relikt zurückholen.\n\nDazu müsst Ihr allerdings einen telemantischen Signalgeber in der Nähe des Auges platzieren. Dadurch kann ich das Auge UND Euch zurück in Sicherheit bringen. Die Allianz wird leer ausgehen.\n\nUnd wenn Ihr schon mal da seid, könntet Ihr vielleicht dem Verantwortlichen für den Diebstahl des Auges meinen \"Dank\" ausrichten.", sourceObjective = "Tötet Urda Terrorflamme und platziert einen telemantischen Signalgeber in der Nähe des Auges von Xibala.", completion = "Ahhh... Es muss so entmutigend sein, wenn man sich auf solche Magie verlassen muss. Gute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[48402] = { id = 48402, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Giftige Berührung", description = "Ihr... Ich sah Euch mit Zentimo sprechen. Bitte, mir bleibt nicht viel Zeit...\n\nDiese Trolle, sie wollen unser Blut. Ich war schon fast ausgeblutet, bevor der hier meinem Gift erlag.\n\nDurchsucht ihn, das Blasrohr und die Pfeile sollten noch da sein. Taucht die Pfeile in mein Blut und nutzt sie, um möglichst viele von ihnen zu schwächen.\n\nMein Tod wird nicht vergebens sein! Wenn diese Trolle unser Blut unbedingt wollen, dann sollen sie es bekommen!", sourceObjective = "Benutzt das Blasrohr, um 5 Blutjägertrolle zu schwächen.", completion = "Wie ich sehe, habt Ihr Mag'ashs Opfer einen Sinn gegeben.\n\nIch danke Euch für Euren Heldenmut, {name}.\n\nBitte, nehmt diese Waffe und geht mit meinem Segen.", sourceObjectiveStatus = "unverified-source-field" }
quests[48403] = { id = 48403, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Finsternis", description = "Jahrtausendelang konnte die Finsternis in Schach gehalten werden. Die Zauberschutze hielten und haben den Hochberg geschützt.\n\nJetzt sind sie fort und das Böse ist wieder frei.\n\nDie Finsternis, die in unsere Träume eingedrungen war und von der selbst die Kobolde nur ängstlich flüsterten... sie ist jetzt hier.\n\nUul'gyneth, der Bote der Alten Götter, bereitet seinen Meistern den Weg. Wenn wir nicht zusammenhalten und ihn besiegen, ist alles verloren.\n\nIhr müsst alles riskieren, um ihn zu bezwingen, Champion. Genau wie wir alle.", sourceObjective = "Besiegt Uul'gyneth, die Finsternis.", completion = "Ich kann kaum in Worte fassen, wie viel Ihr am heutigen Tag für uns getan habt oder wie dankbar ich bin, Euch als Verbündeten zu haben.\n\nWir danken Euch, Held. ICH danke Euch.\n\nIch stehe hierfür tief in Eurer Schuld.", sourceObjectiveStatus = "unverified-source-field" }
quests[48404] = { id = 48404, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Strolche", description = "Ihr da! Habt Ihr funktionstüchtige Beine und braucht Geld? Ich würde Euch gerne anheuern.\n\nDiese verfluchten, unerzogenen, gewissenlosen Straßenkinder haben schon wieder meine Schriftrollen gestohlen. Diese Schriftrollen sind gefährlich, wenn sie in die falschen Hände geraten.\n\nUnd es kommt noch schlimmer: Ich glaube, dass diese kleinen Herumtreiber organisiert sind.\n\nFindet die Straßenstrolche für mich und nehmt ihnen ihre Beute ab. Ich werde Euch dafür bezahlen.", sourceObjective = "Haltet 5 Straßenstrolche vom Stehlen ab.", completion = "Ich schäme mich dafür, Euch für etwas anzuheuern, was ich früher selbst erledigt hätte, aber meine Beine wollen nicht mehr so, wie ich will.", sourceObjectiveStatus = "unverified-source-field" }
quests[48405] = { id = 48405, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herr Nett", description = "Normalerweise bin ich kein gewalttätiger Tortollaner, aber ich kann es einfach nicht ertragen, wenn ein Verbrecher Kinder für seine eigene Profitgier einsetzt.\n\nDiese Straßenstrolche handeln offenbar auf Geheiß eines Anführers. Ich glaube, sie nennen ihn \"Herr Nett\". Dieser Name kann nur sarkastisch gemeint sein.\n\nMit dieser Schriftrolle hier könnt Ihr Euch unbehelligt unter den Straßenstrolchen bewegen. Vielleicht führen sie Euch zu Herrn Nett. Falls Ihr ihn findet, macht ihm den Garaus und ich zahle Euch ein Kopfgeld.", sourceObjective = "Findet und tötet Herrn Nett.", completion = "Exzellent. Ein böser Troll weniger auf den Straßen. Ihr könnt Euch aber darauf einstellen, dass bald jemand seinen Platz einnimmt. So ist es immer.", sourceObjectiveStatus = "unverified-source-field" }
quests[48419] = { id = 48419, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geködert und gefangen", description = "Ihr sucht nach einem Freund vom Wrack?\n\nWenn er überlebt hat, ist er vielleicht den Pfad hoch in unser Lager gelaufen.\n\nUnd wenn er es sich nicht da oben am Feuer gemütlich gemacht hat, dann... Die Sirenen in der Gegend hier haben schon viele Opfer gefordert.\n\nSchaut besser erst im Lager nach, bevor Ihr Euch in den Priel wagt. Erkundigt Euch bei unserer Anführerin, Jette die Klinge. Sie wird schon wissen, wenn ein neuer Überlebender aufgetaucht sein sollte!", sourceObjective = "Sucht nach Finn Schönwind.", completion = "Bah... Habe ich... Habe ich geweint?\n\nLasst uns nie wieder davon sprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[48421] = { id = 48421, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutgetränkte Fluten", description = "Verfluchte schleimige Weibsbilder!\n\nIhr Gesang ergreift die Herzen der Männer und macht ihr Hirn zu Mus.\n\nMein Schiff ist auf Grund gelaufen. Meine Fracht ist verloren.\n\nJetzt bleibt nichts anderes übrig als zu kämpfen!", sourceObjective = "Tötet 8 klagende Sirenen.", completion = "<Kielson steht auf einem Haufen Sirenenleichen und blickt zu Euch auf.>\n\nIch brauch' was zu trinken.", sourceObjectiveStatus = "unverified-source-field" }
quests[48433] = { id = 48433, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zusammen sind wir die Horde!", description = "Was mit einem einfachen Festmahl begann, endete in einer Schlacht gegen das uralte Böse, das die Welt verschlingen wollte.\n\nWas für ein Tag!\n\nIhr habt maßgeblichen Anteil an dem geschlossenen Bündnis zwischen Orgrimmar und dem Hochberg. Diese Tauren stellen einen Gewinn für die Horde dar.\n\nDer Kriegshäuptling wird zufrieden sein.", sourceObjective = "Sprecht mit Ji Feuerpfote in der Botschaft von Orgrimmar, um das Ende dieser Geschichte zu hören.", completion = "Wir scheinen einen neuen Verbündeten gewonnen zu haben. Das habt Ihr gut gemacht.\n\nDie Hochbergtauren sind berühmt für ihre Kampfkünste. Ich freue mich schon auf den Moment, wenn sie über die Allianz herfallen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[48434] = { id = 48434, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie geht es Ebenhorn?", description = "Drei der uralten Zauberschutze sind reaktiviert. Der Berg ist noch nicht sicher, aber wir haben vielleicht genug getan, um Ebenhorn aus den Klauen des Schattens zu befreien.\n\nLasst uns nach Donnertotem zurückkehren und sehen, wie es ihm geht. Vielleicht kann uns Ebenhorn mehr über die Nekrodunklen und den hinterlistigen Meister erzählen, dem sie dienen.", sourceObjective = "Kehrt nach Donnertotem zurück und schaut nach Ebenhorn.", completion = "Ich bin wieder ganz der Alte, {name}.\n\nIhr und Grauhimmel habt mich aus den Fängen der Alten Götter gerettet. Wäre ich noch länger in diesem Zustand verblieben, wäre ich verloren gewesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[48435] = { id = 48435, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geistwandler", description = "Geistwandler Grauhimmel hat mit der Behandlung von Ebenhorn begonnen, aber er hat noch kein Heilmittel gefunden... Er bittet um Eure Hilfe.\n\nBitte sprecht sofort mit ihm, {name}. Die Geistwandler sind die Hüter unserer Vergangenheit. Ich bete, dass sich die Antwort irgendwo in ihren uralten Wahrheiten verbirgt.", sourceObjective = "Sprecht mit Geistwandler Grauhimmel in Donnertotem am Hochberg.", sourceObjectiveStatus = "unverified-source-field" }
quests[48440] = { id = 48440, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die Nacht", description = "Was wir heute tun, tun wir für Azeroth. Für die unzähligen Seelen, die dem grässlichen Kreuzzug der Legion zum Opfer gefallen sind.\n\nSobald Ihr bereit seid, werden wir uns mit der Vindikaar direkt ins Herz der Legion begeben.\n\nArgus erwartet Euch.", sourceObjective = "Reist an Bord der Vindikaar nach Argus.", completion = "Wir müssen schnell handeln!", sourceObjectiveStatus = "unverified-source-field" }
quests[48441] = { id = 48441, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überreste des Sinistren Grats", description = "Meine Reiter haben Talbuks, aber es fehlt ihnen an Vorräten: Nahrung, Werkzeuge, Waffen.\n\nSeit Jahrhunderten ziehen wir von Hütte zu Hütte und immer wieder begeben wir uns auf die Flucht, wenn die Legion uns entdeckt. Doch nie konnten wir dabei unseren Besitz mitnehmen.\n\nIhr seid mächtig und habt fähige Anhänger, aber Ihr kennt Euch auf Argus nicht aus. Die Landschaft wird Euch ebenso gnadenlos entgegenstehen wie die Legion selbst. Beschafft unsere Vorräte vom Sinistren Grat, und ich werde meinen Leuten auftragen, Eure Streitkräfte durchs Argusödland zu geleiten.", sourceObjective = "Benutzt die Späherkarte und schließt die Mission \"Vorräte vom Sinistren Grat\" ab.", completion = "Ihr habt unsere Vorräte zurückgebracht. Wie versprochen, werden wir Eure Streitkräfte auf Argus unterstützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[48442] = { id = 48442, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Nath'raxasfestung: Vorbereitungen", description = "Für die gefangenen Krokul in der Nath'raxasfestung kommen zwei grässliche Schicksale in Frage. Sie können sich dem Bösen beugen und willfährige Soldaten der unendlichen Armee werden oder man verwandelt sie in abstoßende Monstrositäten, die man Ur'zul nennt.\n\nWährend die Armee des Lichts die Aufmerksamkeit der Legion auf sich zieht, werde ich die Möglichkeit haben, meine Leute zu retten. Ich muss Euch um Hilfe bitten.\n\nAber bevor wir loslegen können, müsst Ihr Eure Truppen angemessen ausrüsten.", sourceObjective = "Bringt 6 Champions auf Gegenstandsstufe 900.", completion = "Schon bald werden die Krokul die Nath'raxasfestung stürmen. Meine Leute können es kaum erwarten.", sourceObjectiveStatus = "unverified-source-field" }
quests[48443] = { id = 48443, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Nath'raxasfestung: Rettungsmission", description = "Die Ausrüstung Eurer Streitkräfte sollte ausreichen, um meine Leute vor Nath'raxas zu retten. Befehlt Euren Champions, meinen Angriff zu unterstützen. Zusammen werden wir die Herrschaft der Legion über dieses Gebiet beenden.", sourceObjective = "Benutzt die Späherkarte und schließt die Mission \"Ausbruch aus der Nath'raxasfestung\" ab.", completion = "Wir waren einst eine große Zivilisation. Aber jetzt?... Ich danke Euch, {name}. Unsere vereinten Truppen haben viele Gefangene aus der Nath'raxasfestung befreien können. Jetzt, wo sie weniger Sklaven zur Verfügung haben und die Armee des Lichts ihnen zusetzt, wird der Einfluss der Legion auf dieses Gebiet deutlich schwächer ausfallen.", sourceObjectiveStatus = "unverified-source-field" }
quests[48445] = { id = 48445, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ruinen von Oronaar", description = "Viele Krokul streifen schattenumhüllt in der Stadt unter uns umher. Ich kann nicht akzeptieren, dass sie nicht gerettet werden können.\n\nArkhaan war einst ein Anführer. Einige seiner Anhänger befinden sich vielleicht noch in den Ruinen von Oronaar und wandeln auf dem schmalen Grat zwischen Vernunft und geistigem Niedergang. Bittet Euren Orden um Hilfe. Sucht die Ruinen nach allen ab, die noch gerettet werden können.", sourceObjective = "Benutzt die Späherkarte und schließt die Mission \"Dem Wahnsinn nahe\" ab.", completion = "Eure Champions haben einen Überlebenden in einer Höhle unterhalb von Oronaar entdeckt. Er verbirgt sich vor den Leerenberührten und scheint bei Verstand zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[48446] = { id = 48446, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relikte der uralten Eredar", description = "Ich habe Arkhaan im Stich gelassen. Das wird nicht wieder geschehen. \n\nWenn wir die Krokul befreien wollen, müssen wir Eredath von den Astralen befreien. L'ura ist besiegt, aber die Leere liegt immer noch drückend über dem Schattenwachenvorstoß.\n\nBevor wir anfangen, müsst Ihr Eure Truppen vor den Schatten schützen. Eure Champions sollten in den nahen Ruinen nach alten Eredarwaffen suchen.", sourceObjective = "Bringt 6 Champions auf Gegenstandsstufe 925.", completion = "Die durch den Schattenwachenvorstoß streifenden Leerrufer müssen ausgelöscht werden. Eure Leute sind für diese Konfrontation ausreichend bewaffnet.", sourceObjectiveStatus = "unverified-source-field" }
quests[48447] = { id = 48447, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vertreibung der Schattenwache", description = "Stellt mir noch einmal die Hilfe Eures Ordens zur Seite, damit wir der Bedrohung durch die Schattenwache endgültig ein Ende setzen können. Während Ihr die Legion angreift, werden wir uns der Leere stellen. Der Angriff beginnt, sobald Eure Truppen eintreffen.", sourceObjective = "Benutzt die Späherkarte und schließt die Mission \"Vertreibung der Schattenwache\" ab.", completion = "Nach L'uras Niederlage und dem Ausschalten der Leerrufer ist die Herrschaft der Schattenwache über diese Stadt ins Wanken geraten. Wenn unser Angriff auf die Legion erfolgreich verläuft, haben alle, die in dieser Gegend leben, vielleicht noch eine Chance.", sourceObjectiveStatus = "unverified-source-field" }
quests[48448] = { id = 48448, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Legionskriegsmaschine lahmlegen", description = "{class}t, ich könnte Eure Hilfe brauchen. Die Armee des Lichts plant einen koordinierten Angriff gegen den Geistertiegel, Terminus und die Anhöhe des Formers, um die Legion daran zu hindern, ihren Krieg über die Antorische Ödnis hinaustragen zu können. Wir haben nicht genug Soldaten, um unsere Stellungen zu halten und diese Operation durchführen zu können.\n\nKönntet Ihr nicht als {class} in unserem Namen zu Euren Leuten sprechen? Dieser Schlachtplan könnte aufgehen, wenn sie an unserer Seite kämpfen würden. Wir könnten die Kriegsmaschine der Legion lahmlegen.", sourceObjective = "Benutzt die Späherkarte und schließt die Mission \"Schlachtplan in der Ödnis\" ab.", completion = "Drei gefallene Legionseinrichtungen bei einer Operation. Außerordentlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[48452] = { id = 48452, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Rote Markt", description = "Ihr seid mit Prinzessin Talanji hier angekomm'?\n\nIch brauch Eure Hilfe bei 'ner sehr unappetitlichen Aufgabe. Purpurkultisten ham sich hier 'nen Markt für Blutmagie erschloss'n. Das is' übel, Mann. Richtig übel.\n\nIhr müsst die Trepp'n hinuntersteig'n un' mir alle Hinweise auf Blutmagierituale bring'n, die Ihr findet. Un' zerstört auf jeden Fall ihr'n Kelch. 'n großer Kelch. Vergesst den Kelch nich'.", sourceObjective = "Sammelt 3 dunkle Fetische und zerstört den Kelch der Anrufung.", progress = "In Zuldazar ist diese Magie aus einem bestimmten Grund verbot'n. Man sagt, dass diejenigen, die sie benutz'n, beginn'n, Stimmen zu hör'n. Und Opferung'n, na ja... das mach'n eben nur die niederen Stämme.", completion = "Diese Blutmagie is' wie 'ne Seuche. Wenn man sie nich' stoppt, breitet sie sich unaufhaltsam aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[48453] = { id = 48453, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gegenschlag", description = "Wie Ihr vielleicht mitbekommen habt, entführen die Ritualisten in diesem Wald unsere Leute und führen schreckliche Rituale mit ihnen durch. Die Seelen unserer Verstorbenen wandern nun als entstellte Kreaturen. Solch eine Sünde darf nicht ungestraft bleiben. Tötet so viele Ritualisten, wie Ihr könnt, und beseitigt auf jeden Fall den düsteren Dämon, der sie anführt.", sourceObjective = "Tötet 8 Ritualisten der Eredar und Lady Shahrazad im Versteinerten Wald.", completion = "Ihr wart wirklich eine große Hilfe für meine Tiertreiber. Bitte akzeptiert dies als Zeichen unseres Danks.", sourceObjectiveStatus = "unverified-source-field" }
quests[48454] = { id = 48454, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beweise des Bösen", description = "Jakra'zet weigert sich, in diesem Gebiet zu patrouillier'n. Yazmas Spione hatt'n uns nich' vor dem Übel gewarnt, das unter unsrer Stadt lauert. Un' Zul hat nich' vorausgeseh'n, dass sich direkt vor unsren Augen Blutmagie ausbreitet.\n\nDas sind schwere Anschuldigung'n, un' die Beweise dafür lieg'n in Eurer Hand. Zeigt sie Zolani, der Klinge des Königs. Sie weiß am best'n, was sie bedeuten und wie sie dem König unterbreitet werd'n sollten.", sourceObjective = "Sprecht mit Zolani, der Klinge des Königs.", completion = "Am helllicht'n Tag wird Blutmagie praktiziert? Das darf nich' sein.\n\nIhr habt gut daran getan, mir Bescheid zu sag'n. Ich werd es bei erster Gelegenheit König Rastakhan bericht'n, sobald sein Beraterstab fort ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[48455] = { id = 48455, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämmerschutzproblem", description = "In diesem Wald treiben sich noch immer Arten von Talbuks und Panthara herum. Doch das Gleichgewicht wurde gestört und die Panthara könnten die Talbuks ausrotten. Um ihr Überleben zu gewährleisten, müssen wir die Zahl der Panthara verringern.\n\nLasst sie nicht lange leiden. Ein schneller Tod ist gnadenvoll.", sourceObjective = "Tötet 10 Panthara im Versteinerten Wald.", completion = "Das Gleichgewicht des Waldes zu halten, sichert ihm ein langes Leben.", sourceObjectiveStatus = "unverified-source-field" }
quests[48456] = { id = 48456, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hexendoktorin Jala", sourceObjective = "Findet Hexendoktorin Jala.", completion = "Ich grüß Euch, {class}. Ich bin Hexendoktorin Jala. Ihr kommt genau rechtzeitig.", sourceObjectiveStatus = "unverified-source-field" }
quests[48460] = { id = 48460, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Tiertreiber", description = "Auf Argus gibt es sehr böse Dinge und einige der schlimmsten davon hausen in unseren Wäldern. Meine Tiertreiber befinden sich am Waldrand und warten dort auf Unterstützung. Das wärt dann wohl Ihr.\n\nBegebt Euch zu Vorreiter Jerek. Er wird Euch den Rest erklären.", sourceObjective = "Sprecht mit Vorreiter Jerek im Versteinerten Wald.", completion = "Ich fürchte, den Wald haben wir verloren.", sourceObjectiveStatus = "unverified-source-field" }
quests[48461] = { id = 48461, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo sie es am wenigsten erwarten", description = "Der fanatische Kreuzzug der Legion dünnt ihre eigenen Reihen aus. Während sie sich auf die Verteidigung von Argus konzentriert, können wir ihre Streitkräfte auf anderen Welten angreifen.\n\nReist durch einen Invasionspunkt auf Argus und zeigt der Legion, dass sie sich nicht vor dem Tod verstecken können.", sourceObjective = "Reist durch einen Invasionspunkt und besiegt einen Kommandanten der Legion.", completion = "So viele Legionswelten, die reif zur Eroberung sind...", sourceObjectiveStatus = "unverified-source-field" }
quests[48465] = { id = 48465, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vrax'thul" }
quests[48466] = { id = 48466, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ven'orn" }
quests[48467] = { id = 48467, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Puscilla" }
quests[48468] = { id = 48468, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bwonsamdis Erlösung", description = "Bwonsamdi, der Loa des Todes, hat uns beauftragt, diesen Ort von Untoten zu bereinig'n.\n\nSie werd'n von einem Monster namens Kel'vax kontrolliert.\n\nKönnt Ihr helf'n? Dort drüben zerstör'n Zombies den Tempel von Bwonsamdi und wir sind nich' stark genug, um sie alle zu zerstör'n.\n\nNehmt diese Fackel. Tötet die Zombies und verbrennt ihre Leichen mit der Fackel. So werden ihre Seelen zu Bwonsamdi find'n.\n\nWenn Ihr das tut, sind wir dem Sieg über Kel'vax einen Schritt näher.", sourceObjective = "Verbrennt 10 entweihte Trollleichen mit der Einäscherungsfackel.", completion = "Ihr habt gute Arbeit geleistet. Ich spür', dass Bwonsamdi über die Befreiung seiner Anhänger erfreut is'.", sourceObjectiveStatus = "unverified-source-field" }
quests[48473] = { id = 48473, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Respekt für die Rituale", description = "Wenn wir die Seele von Kel'vax zu Bwonsamdi send'n woll'n, müss'n wir sorgfältig vorgeh'n. Wir müss'n dafür zwei Sachen mach'n.\n\nAls Erstes gibt's beim Tempel in der Nähe noch Fackeln. Zündet die mit der Fackel an, die Ihr von mir habt.\n\nMit den Fackeln ham wir früher angezeigt, dass wir 'n Geist zu Bwonsamdi bring'n. Kel'vax wird begreif'n, dass sein letztes Stündlein geschlag'n hat.\n\nAls Zweites brauch ich 'n spezielles Ritualpulver, das tief im Tempel drin is'. Nur damit könn' wir Kel'vax aufhalt'n.\n\nUn' jetzt geht. Ich bet' darum, dass Bwonsamdi uns beisteh'n wird.", sourceObjective = "Entzündet 5 Ritualfackeln und bergt das Ritualpulver von Shinga Todeswandler.", progress = "Zündet die Fackeln an un' holt das Pulver, damit wir Bwonsamdis Gunst gewinn' könn'.", completion = "Gut! Habt Ihr für 'n Augenblick Bwonsamdis Gegenwart gespürt?", sourceObjectiveStatus = "unverified-source-field" }
quests[48474] = { id = 48474, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gruftwächter" }
quests[48475] = { id = 48475, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geister sehen", description = "Die Geister am Friedhof sind sehr aufgewühlt! Ich würde sie ja selbst fragen, warum, aber mir fehlt die Salbe, die ich normalerweise zur Kommunikation mit den Toten nutze. Meine Familie stellt sie schon seit Ewigkeiten her!\n\nDie Kräuter und Werkzeuge, die ich verwende, befinden sich da drinnen. Dorthin kann ich nicht gehen! Einige der Geister sind einfach jenseits aller Vernunft und greifen sofort an!\n\nSammelt Ihr doch die Kräuter und stellt die Salbe mit meinem Werkzeug her. Dann könnt Ihr einen der ruhigeren Geister fragen, was los ist. Aaron Wappenstein wäre ein guter Kandidat.", sourceObjective = "Sammelt Grabblüten, macht dann eine Salbe, wendet sie an und findet dann Aaron Wappenstein.", progress = "Fremder, helft mir ein wenig! Ich bin in der elenden Magie einer Hexe gefangen und weiß nicht, wie lange ich noch widerstehen kann! Zerstört den Kreis, der mich bindet!", completion = "Eine Hexe hat diesen Ort des Guten mit ihrer elenden Macht infiziert. Fremder, Ihr habt Euch wahrlich als Freund erwiesen. Vielleicht könntet Ihr unsere Erlösung bringen!", sourceObjectiveStatus = "unverified-source-field" }
quests[48476] = { id = 48476, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine geteilte Gruppe", description = "Zu Lebzeiten waren meine Landsleute und ich ebenso tapfere Champions, wie Ihr einer seid. Im Tode sind wir nun mächtige Seelen, die die Hexe zum Stärken ihrer verfluchten Diener nutzen kann.\n\nMit Eurer Hilfe habe ich bisher widerstanden, doch die elende Hexe hat die tapfere Brigitte aus ihrem wohlverdienten Schlaf gerissen. Nun ist sie in einem dieser makabren Konstrukte gefangen. Brigitte soll für die Hexe den Tod über jenes Land bringen, das sie zu beschützen schwor!\n\nBefreit die Seele von Brigitte Quellwasser aus dem Konstrukt, das sie gefangen hält!", sourceObjective = "Befreit die Seele von Brigitte Quellwasser.", completion = "So eine eiternde Beule auf einem Krötenrücken! Mich als Schachfigur zu nutzen! Pfui! Ich werde dafür sorgen, dass sie schreiend in das widerwärtige Loch zurückkehrt, aus dem sie herausgekrochen ist!\n\nHabt Dank. Die Hexe wird für ihre ruchlosen Taten büßen!", sourceObjectiveStatus = "unverified-source-field" }
quests[48477] = { id = 48477, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine fehlt noch", description = "Unser abscheulicher Feind, \"Schwester\" Westwald, führt ihr Werk fort. Nachdem sie mich in die Knie gezwungen hat, hat sie nun meine Partnerin, die schöne Hulda, im Visier.\n\nVon uns Dreien war Hulda die freundlichste und besaß eine ungewöhnliche innere Stärke. Dennoch fürchte ich um sie. Das Verderben einer solchen Seele würde eine wahrhaft furchterregende Kreatur erschaffen.\n\nHaltet das widerwärtige Ritual auf, bevor es Hulda ergreift. Gewährt den Toten ihre Ruhe. Tötet Schwester Westwald und befreit uns aus ihrem Griff!", sourceObjective = "Tötet Schwester Westwald.", completion = "Habt Dank, tapferer Held. Ihr habt uns von dem üblen Einfluss der Hexe befreit und der Verbreitung ihrer Verderbnis ein Ende gesetzt. Eure Handlungen haben unsere Seelen gerettet.\n\nNun können wir ruhen.", sourceObjectiveStatus = "unverified-source-field" }
quests[48478] = { id = 48478, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kel'vax' Heim", description = "Kel'vax' Seele ist an drei Phylakterien gebund'n, die durch sein Voodoo geschützt sind. Selbst, wenn wir ihn vernicht'n, würd' er sich einfach in denen neu bilden.\n\nJetzt, wo Ihr die Fackeln entzündet habt, kehrt meine alte Macht zu mir zurück. Ich kann ein Pulver verzaubern, damit Ihr durch Kel'vax' Voodoo hindurchkommt.\n\nFindet die Phylakterien und bringt sie zu mir. Wir werden Kel'vax ins Auge blick'n, wenn wir ihn vernicht'n.\n\nSollte Euch wohl warnen... Das Pulver kann ein wenig in Eurem Verstand rumpfusch'n. Nachdem Ihr es benutzt, erwart'n Euch vielleicht... Visionen. Habt acht.", sourceObjective = "Benutzt das Geisterpulver von Shinga Todeswandler, um Kel'vax' uraltes, repariertes und makelloses Phylakterium zu ergreifen.", progress = "Für 'ne Chance zur Vernichtung von Kel'vax brauch'n wir die Phylakterien.", completion = "Gut! Das heb' ich mir für später auf. Ich will Kel'vax ins Auge blick'n, wenn wir seine Phylakterien zerschmettern.", sourceObjectiveStatus = "unverified-source-field" }
quests[48479] = { id = 48479, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schützende Knochen", description = "Kel'vax nutzt mächtiges Voodoo, die Art, die Euch sofort töt'n kann, wenn Ihr nicht aufpasst.\n\nIch weiß, wie wir diese Magie aufhalt'n können, aber dafür brauch'n wir Knochen. Einen ganzen Haufen. So'n Glück, dass Kel'vax eine riesige Armee von Skeletten hat.\n\nIhr müsst dort hinausgeh'n und ihre Knochen sammeln. Bringt sie zu mir, dann nutz' ich sie, um uns gegen sein Voodoo zu wappnen.", sourceObjective = "Sammelt 40 verfluchte Knochen.", progress = "Habt Ihr die Knochen? Wenn wir Kel'vax' Voodoo stopp'n woll'n, brauch'n wir sie.", completion = "Gut! Ich benutz' diese Knochen, um Kel'vax' düsteren Voodoo abzuwehr'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[48480] = { id = 48480, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Untergang von Kel'vax", description = "Wir sind bereit, Kel'vax zu töt'n, damit Bwonsamdi über seine Seele richt'n kann. Bevor Ihr loslegt, solltet Ihr noch was wissen.\n\nKel'vax war unser Sohn. Deshalb gab Bwonsamdi uns die Aufgabe, seinen Wahnsinn zu stopp'n.\n\nKeine Ahnung, was Kel'vax dazu führte, sich vor Jahrhunderten von unserem Glauben abzuwend'n... aber so ist es nun.\n\nSelbst ohne seine Untoten ist Kel'vax sehr mächtig. Seid vorbereitet... Das ist unsere Chance, ihm ein Ende zu setz'n und Ruhe zu find'n.", sourceObjective = "Besiegt Kel'vax Todeswandler.", progress = "Ihr müsst Kel'vax ein für alle Mal vernicht'n!", completion = "Das war's dann wohl. Wie Ihr seht, is' Kel'vax in seinen Phylakterien gefangen.\n\nJetzt müss'n wir nur noch die Behälter vernichten, damit Bwonsamdi über ihn urteil'n kann.\n\nOhne Euch hätt'n wir das nich' geschafft. Möge Bwonsamdi über Euch wach'n... und mögt Ihr weise genug sein, um zu entscheiden, wann Ihr Euch auf einen Handel mit ihm einlassen solltet.", sourceObjectiveStatus = "unverified-source-field" }
quests[48483] = { id = 48483, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bitte eines Fremden", description = "Mein Volk... versklavt...\n\nGeschlagen... dem Tode nahe...\n\n<Die Person in der Kutte hebt schwach ihren Arm und übergibt Euch einen kleinen gefüllten Trinkschlauch.>\n\nHelft... uns...", sourceObjective = "Heilt 8 dämonenversklavte Akkordarbeiter.", progress = "Wir... werden... niemals... dienen...", completion = "Eine unter einer Kutte verborgene Person... und sie hat Euch nicht angegriffen?\n\nWie merkwürdig.", sourceObjectiveStatus = "unverified-source-field" }
quests[48489] = { id = 48489, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Türme der Heimat", description = "Meine Schwester, Vereesa, hat mir erzählt, wie es dazu kam, dass sich die Hoch... entschuldigt, die \"Blutelfen\" der Horde angeschlossen haben.\n\nIch habe mich immer noch nicht ganz damit abgefunden.\n\nPrinz Kael'thas hat mein Volk auf Abwege geführt. Ich selbst glaube, dass die meisten Sin'dorei sich von der Horde abwenden würden, wenn sie die Wahl hätten.\n\nAls ich Lor'themar das letzte Mal gesprochen habe, dienten wir zusammen als Weltenwanderer. Er war ein exzellenter Waldläufer und ein guter Mann. Ich hoffe, dass sich das im Laufe der Jahre nicht geändert hat.\n\nKommt. Wir dürfen den Regenten nicht warten lassen.", sourceObjective = "Trefft Alleria Windläufer auf der Insel von Quel'Danas.", sourceObjectiveStatus = "unverified-source-field" }
quests[48492] = { id = 48492, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nehmt die Beine in die Hand", description = "Ich befinde mich in einem kleinen... Dilemma.\n\nMein Trupp hat sich für Fürstin Sylvanas umgesehen, als wir von Schlangenwesen überfallen wurden, die sich selbst als \"Sethrak\" bezeichnen.\n\nWie Ihr klar sehen könnt, wurden mir im Kampf die Beine vom Körper getrennt. Glücklicherweise ist es nur eine Fleischwunde.\n\nWürdet Ihr mir helfen, sie wieder anzubringen? Dann können wir uns daranmachen, diesen Sethrak beizubringen, was Rache ist.", sourceObjective = "Bringt Chadwick Paxtons Beine zurück.", completion = "Ich glaube, ich fühle mich schon deutlich besser. Jetzt ist es an der Zeit für ordentliche Vergeltung.", sourceObjectiveStatus = "unverified-source-field" }
quests[48496] = { id = 48496, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiedervereinigung des Trupps", description = "Nun gut. Unser erster Schritt ist die Rettung meiner Kumpane.\n\nAls uns die Sethrak angriffen, schrien sie etwas von einer Vergrößerung des Sethrakimperiums und der Eroberung von Azeroth. Wie charmant.\n\nSie haben die meisten meiner Kumpane getötet, aber auch einige als Geiseln genommen. Wahrscheinlich, um ihnen einzubläuen, wie glorreich das Sethrakimperium ist.\n\nIch hätte den Rest meiner Leute gerne zurück, falls das geht. Wenn das alles vorüber ist, werde ich bei Fürstin Sylvanas ein gutes Wort für Euch einlegen.\n\n...Auch wenn jemand wie Ihr das wohl kaum nötig hat.", sourceObjective = "Rettet die Überreste von Chadwick Paxtons Trupp.", completion = "Gute Arbeit! Es ist gut, wieder mit meinem Körper und meinem Trupp vereint zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[48497] = { id = 48497, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Machtdemonstration", description = "Diese Viecher, man nennt sie Sethrak, denken doch wirklich, dass wir keine Herausforderung darstellen. Das glauben sie doch nur, weil wir nicht auf einen Kampf vorbereitet waren, als sie uns überfallen haben.\n\nNun gut, vielleicht waren wir keine große Herausforderung. Das bedeutet aber keineswegs, dass wir nicht zurückschlagen werden.\n\nTötet so viele der Sethrak, wie Ihr könnt. Ich weiß nicht, wer sie sind oder was sie beabsichtigen, doch ich weiß eines:\n\nAls sie meinen Trupp angegriffen und mich auseinandergesägt haben, war das ihr Todesurteil.", sourceObjective = "Besiegt 10 Sethrak.", completion = "Gut! Ich konnte ihre Schreie bis hier hören. Sie werden die Horde nicht so schnell vergessen!", sourceObjectiveStatus = "unverified-source-field" }
quests[48498] = { id = 48498, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein Erbarmen für Sithis", description = "Hihi... Danke für die Rettung! Ich könnte Eure Hilfe bei einem kleinen Plan brauchen.\n\nDer Befehlshaber hier ist ein Sethrak namens Sithis. Er hat etwas, das er \"Himmelsruferedelstein\" nennt.\n\nAngeblich suchen sie nach einer Art Schattenmagie in Nazmir, um das Ding so richtig in Gang zu bringen.\n\nHihi... Glücklicherweise hat meine Wenigkeit ihre eigene Schattenmagie! Ihr ja vielleicht auch, ich komme bei all Euren Mächten nicht mehr mit.\n\nBeschafft Sithis' Edelstein, danach wird es RICHTIG amüsant.", sourceObjective = "Holt den Himmelsruferedelstein von Giftzahnrufer Sithis zurück.", progress = "Habt Ihr Ingrids Edelstein? Bitte sagt mir, dass Ihr ihn habt, ihr Gerede darüber wird langsam absolut unerträglich.", completion = "Ingrids Befreiung war ausgezeichnete Arbeit. Sie hat mir von diesem Edelstein erzählt und die Mannschaft hat dafür gestimmt, dass Ihr ihn an unseren Schlangenfeinden testen solltet.", sourceObjectiveStatus = "unverified-source-field" }
quests[48499] = { id = 48499, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück in den Staub", description = "Es scheint, als würden die Sethrak einiges daransetzen, diesen Edelstein zu behalten. Ich frage mich, wo sie ihn überhaupt entdeckt haben.\n\nHm... Vielleicht würde das auch für Fürstin Sylvanas von Interesse sein. Das sollte man im Hinterkopf behalten.\n\nIngrid ist der Ansicht, dass der Edelstein Blitz- und Schattenmagie epischen Ausmaßes entfesseln könnte. Das sind ihre Worte, nicht meine.\n\nMeiner Meinung nach wäre es für alle das Beste, wenn Ihr ihn an der kleinen Sethrakarmee ausprobiert, die dort draußen nach uns sucht.", sourceObjective = "Besiegt 20 wütende Sethrak mit dem Himmelsruferedelstein.", completion = "Gute Arbeit. Die Sethrak werden zurückkehren, doch wir haben ihnen gezeigt, dass man sich nicht mit der Horde anlegen sollte.\n\nJetzt, da das geklärt ist, wird mein Trupp aufbrechen. Hoffentlich werden wir uns unter... netteren Umständen wiedertreffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[48500] = { id = 48500, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine kurze Ruhepause", description = "Nach all dem, was wir erlebt haben, dürfen wir uns nicht von unserer Vergangenheit ablenken lassen. Wir müssen nach vorn blicken und uns auf das Kommende vorbereiten.\n\nNutzt diese Gelegenheit, um die Vindikaar zu erkunden.", sourceObjective = "Sprecht mit Konstrukteurin Shela'na, Thelbus Bohrnick und Hohepriesterin Ishanah.", progress = "Möge das Licht Euch den Weg weisen.", completion = "Seid Ihr bereit, Eure Reise fortzusetzen?", sourceObjectiveStatus = "unverified-source-field" }
quests[48502] = { id = 48502, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Naroua, König des Waldes" }
quests[48504] = { id = 48504, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die alten Straßen entlang", description = "Fräulein Kronsteig hat mich mit der Sicherung der Stadt Falkenforst und der Dienste des dort ansässigen Alchemiemeisters Eschtal beauftragt. Wie ich allerdings erfahren musste, hat seit einiger Zeit niemand mehr etwas aus Falkenforst gehört.\n\nDer Luftraum über dem Wald ist unpassierbar, daher müssen wir die alte Straße durch die Drustruinen in den Bergen nehmen. Eine kleine und fähige Gruppe hat bessere Chancen, die anwachsenden Truppen der Hexen zu umgehen und Alchemiemeister Eschtal zu retten.\n\nIch bitte Euch deshalb, mir dabei zu helfen.", sourceObjective = "Trefft Euch mit Inquisitorin Morgenlicht bei Gol Osigr.", completion = "Irgendetwas hat die Geister hier gestört.\n\nDie Geister der Verstorbenen kämpfen noch immer gegen Konstrukte und die wandernden Toten.\n\nWir wollen eigentlich nach Falkenforst, aber eine kurze Untersuchung dieses Bereichs könnte uns im Kampf gegen unsere Feinde Vorteile bieten.", sourceObjectiveStatus = "unverified-source-field" }
quests[48505] = { id = 48505, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verliebt und verloren", description = "Oah, mein Kopf. Mein HERZ.\n\nEs fühlt sich an wie eine Mischung aus ausgewachsenem Kater und bitterlichem Herzschmerz.\n\nDie gute Nachricht ist, dass ich zu wissen glaube, wo wir sind. Und wohin das Schiff unterwegs war.\n\nFreihafen.\n\nDas ist eine... freie Stadt. Für, äh... freie Leute. Die einzige Regel dort besagt, dass es keine Regeln gibt. Da gibt es viele Leute mit Holzbeinen, Augenklappen und exotischen Haustieren. Ist klar, was ich meine?\n\nEs gibt einen Weg durch die Hügel, der dorthin führt. Ich bin mir ziemlich sicher, dass ich mich noch an den Weg erinnere...\n\nLasst uns gehen. Nur weg von diesem verdammten Sirenenhexenzeug.", sourceObjective = "Begleitet Finn nach Freihafen.", completion = "Ich sagte doch, dass ich weiß, wie wir es finden!", sourceObjectiveStatus = "unverified-source-field" }
quests[48506] = { id = 48506, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hand des Schicksals", description = "Seit die Legion in die Exodar gedrungen ist, haben die Draenei hart daran gearbeitet, die Rückkehr nach Argus vorzubereiten. Nun haben sie endlich ein Gefährt, das uns dorthinbringen kann.\n\nDa der Weg zu dieser grauenvollen Welt nun offensteht, gibt es keinen besseren Zeitpunkt, um zuzuschlagen. Prophet Velen hat Euch höchstpersönlich aufgerufen, die Angriffsstreitmacht zu verstärken.\n\nIhr solltet Euch sofort zum Hafen von Sturmwind begeben. Es wurde schon ein Schiff beauftragt, das Euch zur Azurmythosinsel bringen wird.", sourceObjective = "Trefft Euch mit Eurer Eskorte zur Exodar im Hafen von Sturmwind.", completion = "Ich bin froh, dass auch Ihr für die Expedition nach Argus ausgewählt wurdet. Es warten jede Menge Kämpfe auf uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[48507] = { id = 48507, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hand des Schicksals", description = "Seit die Legion die Exodar überfallen hat, haben die Draenei hart daran gearbeitet, die Rückkehr nach Argus vorzubereiten. Nun haben sie endlich ein Gefährt, das uns dorthinbringen kann.\n\nDa der Weg zu dieser grauenvollen Welt nun offensteht, gibt es keinen besseren Zeitpunkt, um zuzuschlagen. Prophet Velen hat Euch höchstpersönlich aufgerufen, die Angriffsstreitmacht zu verstärken.\n\nIhr solltet Euch sofort zur Messerbucht begeben. Es wurde schon ein Schiff beauftragt, das Euch zur Azurmythosinsel bringen wird.", sourceObjective = "Trefft Euch mit Eurer Eskorte zur Exodar in der Messerbucht.", completion = "Ich wusste, dass Ihr unter den ausgewählten Kämpfern sein würdet. Es wird mir eine Ehre sein, an Eurer Seite zu kämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[48509] = { id = 48509, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kommandant Sathrenael" }
quests[48510] = { id = 48510, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kommandantin Vecaya" }
quests[48511] = { id = 48511, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kommandant Endaxis" }
quests[48512] = { id = 48512, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwester Subversia" }
quests[48513] = { id = 48513, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invasionspunktoffensive", description = "An den Invasionspunkten sind wir in der Lage, die Legion auf Argus von ihrer Verstärkung abzuschneiden. Wenn wir ihre Truppen in den geringen Rissen besiegen, können wir größere Invasionspunkte angreifen und die Legion dort niederstrecken.", sourceObjective = "Schließt 3 Invasionspunkte ab.", progress = "Die Offensive geht weiter.", completion = "Die Niederlage der Legion steht kurz bevor.", sourceObjectiveStatus = "unverified-source-field" }
quests[48514] = { id = 48514, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlummernde Ungetüme" }
quests[48515] = { id = 48515, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Silberne Klingen", description = "<Dieser Drustkrieger ist vor langer Zeit einer silbernen Klinge erlegen. Trotz ihres Alters sieht die Klinge noch gut aus.\n\nVielleicht könnten diese Waffen noch einmal im Kampf gegen die Drust ihren Zweck erfüllen.>", sourceObjective = "Sammelt 6 angelaufene Klingen von den gefallenen Verteidigern.", sourceObjectiveStatus = "unverified-source-field" }
quests[48516] = { id = 48516, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Giftige Gefilde", description = "<Ein Reisender/Eine Reisende>? Nur, wer lebensmüde ist, würde diesen Weg betreten.\n\nDie einzigen Viecher, die noch giftiger sind als die Markschwirrer, sind die Saurolisken, die sie den ganzen Tag fressen.\n\nIch bin wegen dem Markschwirrergift hier. Na ja, ich handle mit... öhm... Spezialitäten. Meine Kunden sind ganz verrückt nach meinem Produkt. Hah.\n\nWenn Ihr mir ihre Stacheln bringt, bezahle ich Euch dafür. So einfach ist das. \n\nWenn Ihr Euch nicht scheut, Euch die Hände schmutzig zu machen, könnt Ihr sie auch in den Saurolisken finden.", sourceObjective = "Sammelt 50 Giftstacheln.", progress = "Habt Ihr die Stacheln?", completion = "Ein Vergnügen, mit Euch Geschäfte zu machen.\n\nDas nächste Mal bekommt Ihr von mir einen Sonderrabatt. Hah.", sourceObjectiveStatus = "unverified-source-field" }
quests[48517] = { id = 48517, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehrenhafte Entladung", description = "Einige Geister auf dem Schlachtfeld sind so erschöpft, dass sie nicht mehr weitermachen können. Sie waren tapfere Kämpfer aus Kul Tiras. Sie haben ihren Frieden mehr als verdient, aber ihr Pflichtgefühl hält sie hier fest.\n\nBefehlt den Schwächsten unter ihnen, das Schlachtfeld zu verlassen. Hoffentlich könnt Ihr sie davon überzeugen, endlich zu ruhen.", sourceObjective = "Entlasst 10 erschöpfte Geister vom Schlachtfeld.", completion = "Es ist schön, dass ihre Geister sich nun erneut zur letzten Ruhe betten können. Mögen sie nie wieder gestört werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[48518] = { id = 48518, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Retten, wen wir können", description = "Diese Kreaturen haben es wohl darauf abgesehen, unsere Leute gefangen zu nehmen... Wir wissen aber noch nicht so recht, warum.\n\nAn die in der Stadt kommen wir momentan nicht so einfach heran, doch vielleicht können wir einige der Waldarbeiter retten, die entlang des Ufers arbeiten.\n\nBegebt Euch ins Waldgelände östlich von hier und findet heraus, ob es noch Überlebende gibt. Wir können sie hier unterbringen, bis wir ihnen sicheres Geleit von hier fort bieten können.", sourceObjective = "Findet 6 verängstigte Waldarbeiter am Abgeholzten Ufer.", completion = "Gute Arbeit, {class}! Selbst, wenn wir die Stadt nicht zurückerobern können, tut es gut, zu wissen, dass wir ein paar der Unseren gerettet haben.\n\nNun müssen wir sie nur noch von hier fortbringen...", sourceObjectiveStatus = "unverified-source-field" }
quests[48519] = { id = 48519, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hoffentlich können sie nicht schwimmen", description = "Gleich dort drüben liegt ein kleines Boot. Wenn wir die Dorfbewohner sicher an Bord bringen können, sollten sie es über den Fluss bis nach Fallhafen schaffen.\n\nIhr habt zweifelsohne ein Talent für den Kampf. Werdet Ihr uns die Angreifer vom Leib halten, während wir die Dorfbewohner in Sicherheit bringen?", sourceObjective = "Verteidigt die Dorfbewohner, während sie an Bord des Boots am Abgeholzten Ufer gehen.", progress = "Sobald Ihr uns das Zeichen gebt, beginnen wir mit der Evakuierung.", completion = "Ich danke Euch, {class}. Diese Dorfbewohner verdanken Euch ihr Leben.\n\nDa sie nun in Sicherheit sind, können wir uns darauf konzentrieren, die Stadt zurückzuerobern.", sourceObjectiveStatus = "unverified-source-field" }
quests[48520] = { id = 48520, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die drei Schwestern", description = "Wenn Ihr den Namen von Fräulein Kronsteig von all dem reinwaschen möchtet, müsst Ihr Euch in die Stadt begeben. In letzter Zeit sehe ich immer wieder bizarr gekleidete Frauen zwischen den Kreaturen. Sie scheinen dort das Sagen zu haben.\n\nVermutlich stellen sie den Schlüssel zu diesem Alptraum dar, doch wir gelangen nicht in die Stadt, um sie befragen zu können. Es scheint, als wären ihre Diener kein Hindernis für Euch.\n\nWenn Ihr es zu den Frauen schafft, werdet Ihr womöglich Antworten erhalten, die uns beide interessieren. Doch habt acht, sie werden Euch gegenüber kaum wohlwollend sein.", sourceObjective = "Stellt Schwester Eschbrunn, Schwester Früh und Schwester Mooring in Schnitztal.", completion = "Sie wollten nicht reden? Wie ungünstig.\n\nAber immerhin sind sie jetzt weg und wir können die Stadt vielleicht zurückerobern.", sourceObjectiveStatus = "unverified-source-field" }
quests[48521] = { id = 48521, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bezaubern der Leblosen", description = "<Ihr habt in Fallhafen gesehen, wie mit einem solchen Talisman ein Weidenkonstrukt kontrolliert wurde.\n\nWenn Ihr herausfindet, wie er funktioniert, könntet Ihr damit vielleicht die Kontrolle über eines der Weidenkonstrukte des Zirkels übernehmen.>", sourceObjective = "Probiert den Weidentalisman bei einem der inaktiven Verheerer in Schnitztal aus, um zu lernen, wie Ihr ihn kontrollieren könnt.", completion = "Ihr konntet eine ihrer Schöpfungen steuern?! Wirklich beeindruckend!\n\nDas könnte der Wendepunkt sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[48522] = { id = 48522, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein aufschlussreicher Brief", description = "<Die mysteriöse Frau hatte einen Brief von jemandem namens \"Matrone Levae\" bei sich. Offensichtlich hat sie den Befehl, Schnitztal einzunehmen.\n\nDas könnte der Beweis sein, dass Luzilla Kronsteig unschuldig ist. Das wird Bürgermeisterin Minder sicher brennend interessieren.>", sourceObjective = "Kehrt zu Evelyn Minder zurück.", completion = "Anscheinend haben wir uns geirrt. Fräulein Kronsteig war wohl einfach zur falschen Zeit am falschen Ort.\n\nDas heißt aber auch, dass Schnitztal vielleicht in noch viel größerer Gefahr schwebt.", sourceObjectiveStatus = "unverified-source-field" }
quests[48523] = { id = 48523, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die mörderische Matrone", description = "Ich weiß, dass Ihr bereits habt, wonach Ihr suchtet, aber ich habe noch eine Bitte an Euch. Dieser Ort ist nicht sicher, solange diese Matrone Levae noch lebt.\n\nLaut diesem Brief muss sie sich in dieser Höhle verschanzt haben. Niemand von uns hat es geschafft hineinzukommen, aber ich habe gesehen, wie ihre Konstrukte reingehen!\n\nDieser Talisman, den Ihr gefunden habt, könnte der Schlüssel sein. Wenn Ihr damit einen der Weidenmänner kontrollieren und auf sie ansetzen könnt, haben wir vielleicht eine Chance!", sourceObjective = "Steuert den inaktiven Verheerer und besiegt Matrone Levae in der Ursteinmine.", completion = "Es hat funktioniert?! Beim Klabautermann! Ihr habt uns wirklich die Haut gerettet!\n\nIch weiß nicht, wie wir das wiedergutmachen können, aber nehmt schon einmal dies!", sourceObjectiveStatus = "unverified-source-field" }
quests[48524] = { id = 48524, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ziel ist der Zirkel", description = "Wenn die Mine wirklich ihr Ziel war, dann haben sie da drinnen sicher noch viel mehr Kämpfer.\n\nMeine Männer und ich werden vielleicht mit dem Rest hier draußen fertig, aber wenn eine noch größere Streitmacht aus der Mine kommt, haben wir keine Chance.\n\nWenn Ihr sowieso schon die Matrone mit diesem Weidending jagt, könnt Ihr doch vielleicht... Ihr wisst schon... sie ein bisschen aufmischen?", sourceObjective = "Tötet 25 Diener von Matrone Levae in der Ursteinmine.", completion = "Das... soll also heißen, dass es in den Minen noch schlimmer war?\n\nWisst Ihr was? Erzählt mir einfach nichts weiter davon. Wenn Ihr getötet habt, was immer das war, sind wir erst einmal auf der sicheren Seite...", sourceObjectiveStatus = "unverified-source-field" }
quests[48525] = { id = 48525, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Macht sie zu Kleinholz" }
quests[48526] = { id = 48526, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Selbstversenkung" }
quests[48527] = { id = 48527, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unersättliche Landhaie", description = "Der Kriegsbestienkral is' wichtig für das Reich. Alle Tiere, die unsre Waren zieh'n, die Streitkräfte befördern und in unsren Schlachten kämpf'n, sind hier gebor'n und aufgewachs'n.\n\nWenn Ihr die Unterstützung von Rastakhan wollt, müsst Ihr uns beeindruck'n. Ich lass mir was einfall'n, mit was Ihr am besten anfang'n könnt.\n\nWir ham 'n Problem mit den Dimetrodons. Normalerweise is' das keine große Sache, aber dieses Jahr sind wirklich viele von ihnen geschlüpft. Sie brech'n in unsre Pferche ein und fress'n unsre Eier.\n\nTötet Dimetrodons, schützt unsre Tiere und wir werd'n seh'n, wie es weitergeht.", sourceObjective = "Tötet 9 gefräßige Dimetrodons.", completion = "Das scheint Euch zu lieg'n. Das macht Ihr doch nich' zum erst'n Mal.", sourceObjectiveStatus = "unverified-source-field" }
quests[48529] = { id = 48529, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Immer dieser Hunger", description = "Wir ham nich' mehr viele Vorräte übrig.\n\nMojambo un' seine Bande werd'n bald zurück sein un' uns erledig'n woll'n. Aber ohne Nahrung un' Vorräte gibt's hier dann nix mehr zu erledig'n.\n\nUnser Koch sucht wen, der Vorräte beschafft, damit wir das Lager versorg'n könn'.\n\nSprecht mit ihm un' versucht, ihm die Sachen zu besorg'n, die er braucht.", sourceObjective = "Sprecht mit Sezahjin.", completion = "Ihr seid neu hier, oder? Das is' keine gute Zeit, sich unsrem Stamm anzuschließ'n. Ihr hättet wahrscheinlich mehr Glück, wenn Ihr Trugbildern in der Wüste nachlauf'n würdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[48530] = { id = 48530, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herde gesucht", description = "Unsre Alpakaherde is' heut Morgen verlor'n gegang'n.\n\nSieht vielleicht so aus, als hätt'n wir wichtig're Dinge zu tun, aber das Fleisch un' die Milch der Alpakas sin' für uns überlebenswichtig.\n\nDie Alpakas überleb'n nich' lang in diesen Dünen. Sprecht mit Mugjabu und helft ihm bei der Suche nach den Alpakas, bevor's zu spät is'!", sourceObjective = "Sprecht mit Mugjabu.", completion = "Razgaji schickt Euch? Ich weiß gar nich', warum ihm das so wichtig is'. Wenn Mojambo un' seine Bande zurückkomm'n, sin' wir sowieso alle tot...", sourceObjectiveStatus = "unverified-source-field" }
quests[48531] = { id = 48531, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eigenartiges Fleisch", description = "Vielleicht is' Mojambos Bande bald da, um uns umzubring'n, aber wir müss'n trotzdem ess'n, un' wenn man in 'nem unwirtlichen Sumpf lebt, muss man mit dem klarkomm', was man hat.\n\nManchma' findet man kein frisches Fleisch.\n\nUn' deswegen hab ich mir die berühmte eigenartige \"Fleisch\"-Pastete ausgedacht.\n\nDie Geheimzutat dabei sin' Mistkäfer, aber wenn man die gut würzt, schmeckt man das gar nich'!\n\nUnsre Vorräte sin' jetz' fast alle un' deswegen muss so schnell wie möglich wer Mistkäfer jag'n geh'n!", sourceObjective = "Sammelt 8 Mistkäferinnereien ein.", progress = "Habt Ihr die \"eigenartige Zutat\" für die eigenartige \"Fleisch\"-Pastete?", completion = "Jetzt schaut Euch mal diese saftig'n Innerei'n an! Damit könn'n wir genug \"Fleisch\"-Pastet'n für das ganze Lager mach'n!", sourceObjectiveStatus = "unverified-source-field" }
quests[48532] = { id = 48532, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alpakas vom Acker", description = "Unsre Alpakaherde is' heut Morgen abgehau'n. Die lauf'n jetz' grade irgendwo in den Dünen rum.\n\nIs' vielleicht auch besser so. Wenn Mojambo zurückkommt, sin' wir sowieso alle tot.\n\nAber Ihr scheint sie ja zu mög'n. Ihr könnt diese Alpakapfeife hier nehm'n, um sie zusamm'zuruf'n. Ich pfeif jeden Tag zur Fütterungszeit auf der Pfeife. Wenn die Alpakas das hör'n, komm' sie normalerweise gleich angerannt.", sourceObjective = "Treibt 6 Alpakas zusammen.", completion = "Ihr scheint 'n Großteil der Herde gefund'n zu hab'n. Gute Arbeit. Auch wenn Mojambo un' seine Bande uns wohl bald im Schlaf meucheln un' sich dann die Alpakas nehm'n werd'n...", sourceObjectiveStatus = "unverified-source-field" }
quests[48533] = { id = 48533, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frittiertes Huhn nach Vol'dunart", description = "Habt Ihr schon ma' mein köstliches frittiertes Huhn nach Vol'dunart probiert?\n\nIch auch noch nich'! Das liegt wohl daran, dass es in Vol'dun keine Hühner gibt.\n\nAber Bussarde gibt's genug. Warum versucht Ihr nich', ein wenig leck'res Bussardfleisch aufzutreib'n?\n\nDas Geheimnis bei köstlichem frittiertem Huhn is', das Fleisch vorm Frittier'n zu röst'n, aber das funktioniert nur mit frisch'm Fleisch.\n\nIch hab diese Pfeile hier in Alpakafett getränkt. Wenn Ihr die anzündet un' damit die Vögel abschießt, werd'n die geröstet, noch bevor sie tot sind!", sourceObjective = "Sammelt 8 geröstete Bussarde.", progress = "Habt Ihr das Bussardfleisch?", completion = "Das is' vielleicht kein Hühnchen, aber Essen is' es! Wenn man das genug würzt, merkt keiner den Unterschied!\n\nSchmeckt doch sowieso alles wie Hühnchen, oder nich'?", sourceObjectiveStatus = "unverified-source-field" }
quests[48534] = { id = 48534, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fletschzahn hat ausgelacht", description = "Wir müss'n uns nich' nur wegen Mojambos Bande Sorgen mach'n, sondern auch nachts immer gut aufpass'n wegen den Angriffen von den Hyänen.\n\nUn' die gefährlichste von den Hyänen is' Fletschzahn. Er greift nachts die Herde an un' dann kann man immer sein irres Lachen hör'n.\n\nIch will, dass Ihr die Bestie ein für alle Mal erledigt! Fletschzahns Höhle is' südlich der Arena im Verdorrt'n Becken.", sourceObjective = "Besorgt Fletschzahns Kopf.", progress = "Habt Ihr Euch um Fletschzahn gekümmert?", completion = "Gut, dass diese fiese Hyäne bekomm'n hat, was sie verdient! Wenn Ihr stark genug seid, um Fletschzahn zu töt'n, hab'n wir vielleicht sogar 'ne Chance gegen Mojambos Bande...\n\nAber das is' wohl nur Wunschdenken. Wir sin' so gut wie tot...", sourceObjectiveStatus = "unverified-source-field" }
quests[48535] = { id = 48535, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nazmir, der verbotene Sumpf", description = "Die Horde hat Prinzessin Talanji versproch'n, dass wir uns um diese Bluttrolle in Nazmir kümmern, bevor sie Zuldazar angreif'n könn'.\n\nNehmt 'nen Pterrordax und fliegt zu Talanjis Lager in Nazmir. Wir wart'n dort auf Euch.\n\nBereitet Euch gut vor, {name}. In Nazmir gibt's keine Zivilisation, nur uns un' was immer dort lauert.", sourceObjective = "Sprecht mit Rokota und reitet auf einem Pterrordax zu Prinzessin Talanjis Lager in Nazmir.", completion = "Gut, Ihr habt's geschafft. Wir musst'n uns beeilen, um nich' in irgendwelche Ränke verstrickt zu werd'n.\n\nMach'n wir weiter.", sourceObjectiveStatus = "unverified-source-field" }
quests[48538] = { id = 48538, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein wasserdichtes Alibi", description = "Wir werden eine Weile brauchen, um die restlichen Bestien zu beseitigen, aber ich bin sicher, dass wir Schnitztal zurückgewinnen können. Dank Euch!\n\nHier, bringt diesen Brief zum Wachtmeister. Das wird den Namen von Fräulein Kronsteig reinwaschen.\n\nEs tut mir leid, dass Ihr das alles mit ansehen musstet, <Festländer/Festländerin>. Wir sind ein friedliches Volk, aber die Zeiten zwingen uns zur Härte.", sourceObjective = "Bringt Evelyn Minders Brief zu Wachtmeister Henri Leumder bei der Galgenschäre.", completion = "Was ist das? Ein Brief von Bürgermeisterin Minder?\n\n<Wachtmeister Leumder liest Evelyns Brief.>\n\nHmm... Wir haben uns wohl... geirrt.", sourceObjectiveStatus = "unverified-source-field" }
quests[48539] = { id = 48539, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freihafen", description = "Na also, da ist es: Freihafen.\n\nWenn Ihr bezahlen könnt, bekommt Ihr dort alles. \n\nOb Ihr mit Gold oder mit Stahl bezahlt, liegt ganz bei Euch.\n\nSeht es Euch an.", sourceObjective = "Benutzt Finns Fernrohr.", progress = "Also, ich habe vielleicht einige ungewöhnliche Angewohnheiten, aber nichts Ansteckendes.\n\nBenutzt doch einfach das Fernglas, in Ordnung?", completion = "Seid Ihr bereit, Euch kopfüber in eine Schlangengrube zu stürzen?", sourceObjectiveStatus = "unverified-source-field" }
quests[48540] = { id = 48540, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unterstützung für die Werft", description = "So lang ich schon das Meer beobachte, habe ich es noch nie so aufgewühlt gesehen. Es ruft die Gezeitenweisen an und fleht um Hilfe.\n\nUnter den Dorfbewohnern grassiert eine Krankheit, und sie scheint vom Meer zu stammen.\n\nWir sind nur so wenige. Wir wissen uns selbst kaum zu helfen!\n\nIch bitte Euch, nehmt diese Liste und versucht, die Reagenzien auf dem Pier aufzutreiben, während ich die Leute zu beruhigen versuche. Ich müsste damit ein Tonikum herstellen können, das ihnen hilft.\n\nHoffe ich zumindest...", sourceObjective = "Sammelt ein Säckchen Seetang, ein Pergamentbündel und ein wenig Robbentran in der Nähe der Angelpunktwerft.", progress = "Zu meiner täglichen Arbeit zählen das Segnen von Schiffen, die Beobachtung des Meeres und das Auffinden der besten Fischgründe.\n\nIch fürchte, mit dieser Sache bin ich etwas überfordert.", completion = "Kein Seetang? Was sollen wir denn jetzt machen?", sourceObjectiveStatus = "unverified-source-field" }
quests[48542] = { id = 48542, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gegenschlag", description = "Die Schriftrolle beschreibt einen düsteren Zauber, der die Seelen der benachbarten Krokul stiehlt, um einen neuen Dämon zu erschaffen: den Ur'zul. Diese Schriftrolle wurde von Lady Shahrazad signiert.", sourceObjective = "Tötet 8 Ritualisten der Eredar und Lady Shahrazad im Versteinerten Wald.", completion = "Ihr wart wirklich eine große Hilfe für meine Tiertreiber. Bitte akzeptiert dies als Zeichen unseres Danks.", sourceObjectiveStatus = "unverified-source-field" }
quests[48544] = { id = 48544, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruhig, Brauner!", description = "Ihr habt meinen Dank, {name}. Meine Tiertreiber sollten jetzt allein zurechtkommen. Dürfte ich Euch um noch einen Gefallen bitten? Könntet Ihr Häuptling Hatuun eine Nachricht überbringen? Sagt ihm, dass der Wald wieder sicher ist. Er wird Euch bestimmt für Eure Mühen belohnen.\n\nIch stelle Euch einen meiner schnellsten Klippensteiger für die Reise zur Verfügung. Schaut in beide Richtungen, bevor Ihr den Pfad außerhalb dieses Waldes überquert. Dort patrouilliert nämlich ein riesiger Legionsvernichter. Viel Glück!", sourceObjective = "Kehrt zu Häuptling Hatuun im Krokullager zurück.", completion = "Die Tiertreiber sind hier der Schlüssel für unser Überleben. Wenn Ihr ihnen geholfen habt, sollt Ihr belohnt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[48547] = { id = 48547, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quest" }
quests[48548] = { id = 48548, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quest", description = "Ihr habt jetzt die energiegeladenen Sporen und fühlt Euch genötigt, sie auf die Sporenhalme da unten zu werfen...", sourceObjective = "Verwendet Eure Fähigkeit 'Sturzflug', um die Sporenhalme weiter unten zu zermalmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[48549] = { id = 48549, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grozztok der Schwarzherzige", description = "'ne Gruppe von uns wurd hier zum Sterb'n zurückgelass'n. \n\nIn unsrer ersten Nacht im Lager ham mich die erstickten Schreie von andren Verbannt'n geweckt. Jakra'zet hatte Assassinen in unser Lager geschickt, die nach Rakera gesucht ham.\n\nIhr Anführer, Grozztok, is' auf mich losgegang'n, aber Rakera hat eingegriff'n. \n\nSie hat ihn bis in die Dünen verfolgt, aber das is' schon Tage her. \n\nWenn Ihr auf Grozztok trefft, könnt Ihr ihm gleich 'ne Klinge in sein dunkles Herz ramm'.", sourceObjective = "Tötet Grozztok innerhalb von Atul'Aman.", completion = "Ihr habt Jakra'zet geseh'n? Warum sollte er versuch'n, in die alte Pyramide einzubrech'n? \n\nWas er auch vorhat, es is' bestimmt nix Gutes.", sourceObjectiveStatus = "unverified-source-field" }
quests[48550] = { id = 48550, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gestohlene Säckchen", description = "Einer aus unsrer Gruppe hat von 'nem Tempel im Gebirge gesproch'n, wo Verbannte unterkomm' könn'. Aber ohne 'ne Opfergabe für den Loa kommt man da nich' rein.\n\nIch würd alles geben, um irgendwo in dieser Ödnis unterzukomm', aber diese Assassinen ham alles geklaut un' jetz' hab ich nix mehr.\n\nWir hatt'n alle 'n Säckchen mit Sachen dabei. Nich' zu viel, aber mehr, als 'n Troll so unbedingt braucht. \n\nWenn Ihr in den Dünen nach Eurer Freundin schaut, könnt Ihr dann vielleicht auch nach unsren Säckchen schau'n?", sourceObjective = "Holt 5 verwitterte Säckchen von Assassinen der Sandwüter zurück.", progress = "Habt Ihr unsre Sachen bekomm'n?", completion = "<Jorak untersucht kurz die Säckchen.>\n\nDa fehlt 'ne ganze Menge. Hoffentlich is' noch genug für 'ne Opfergabe da.", sourceObjectiveStatus = "unverified-source-field" }
quests[48551] = { id = 48551, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wässern oder Welken", description = "Die Pflanzen in diesem Gebiet waren nicht immer so aggressiv. \n\nOhne Wasser verdorren und verwelken die Distelranken, bis sie kaum noch erkennbar und sehr bösartig geworden sind.\n\nNehmt meine Gießkanne und gießt die verdorrenden Distelranken, damit sie nicht zu Fleischfressern werden.", sourceObjective = "Verwendet Ranahs Gießkanne, um 10 verdorrte Distelranken zu gießen.", completion = "Schaut, wie glücklich diese Pflanzen sind! Das ist Euer Verdienst.", sourceObjectiveStatus = "unverified-source-field" }
quests[48553] = { id = 48553, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lasst es sprudeln", description = "Die Brunnen hier sahen schon einmal besser aus. Im Moment können sie kein Wasser speichern, aber das können wir reparieren!\n\nIhr könnt mein Ersatzwerkzeug benutzen, um die Risse zu schließen. \n\nMit ein wenig Glück und Geschick werden die Brunnen im Handumdrehen wieder mit Wasser gefüllt sein!", sourceObjective = "Repariert die Brunnen in der Verdorrenden Schlucht.", completion = "Hm, der Brunnen vor mir funktioniert immer noch nicht? Aber ich habe fehlerfrei gearbeitet!", sourceObjectiveStatus = "unverified-source-field" }
quests[48554] = { id = 48554, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Problemquelle", description = "Ich habe meine Arbeiten an diesem Brunnen mehrfach überprüft. Ich habe keine Fehler gemacht. \n\nEs muss ein Problem an der Quelle geben. \n\nDer Brunnen bezieht sein Wasser aus einem nicht allzu großen Becken oberhalb der Terrasse. \n\nKönntet Ihr dort bitte einmal nachsehen?", sourceObjective = "Helft Ranah, die Ursache für die Fehlfunktion des Brunnens auf der Verdorrenden Terrasse auszumachen.", completion = "Schlangen also! Das erklärt die Sache. Ich bin froh, dass Ihr die Verstopfung beseitigen konntet. Die Schlucht sieht auch schon viel grüner aus!", sourceObjectiveStatus = "unverified-source-field" }
quests[48555] = { id = 48555, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Saat ist noch zu retten", description = "Ich habe die Flora auf der Terrasse ausgiebig studiert. Ist eine Distelranke vollständig ausgetrocknet, kann man die Pflanze nicht mehr retten. \n\nAber ihre Samen sind dann immer noch fruchtbar. Unter den richtigen Bedingungen kann man mit ihnen neue, gesunde Distelranken züchten. \n\nSammelt ein paar Samen von den fleischfressenden Distelranken ein, die nicht mehr gerettet werden können, und pflanzt sie in die fruchtbaren Erdhaufen.\n\nDistelranken beginnen sehr schnell zu wachsen. Die Terrasse sollte also im Nu wieder mit Pflanzen gefüllt sein!", sourceObjective = "Pflanzt 8 Distelrankensamen in fruchtbare Erde auf der Verdorrenden Terrasse ein.", completion = "Habt Ihr gesehen, wie hier alles wieder aufblüht? Ihr habt ja einen richtig grünen Daumen.", sourceObjectiveStatus = "unverified-source-field" }
quests[48557] = { id = 48557, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Setzlinge setzen", description = "Algerson zerstört die Wälder und hinterlässt nichts als Leere! Wir müssen uns um Azeroth kümmern und dabei helfen, dass es wieder leben und gedeihen kann!\n\nNehmt diese Samen, sucht nach dem Boden, der nach ihnen verlangt, und helft unserem Planeten, seine einstige Anmut und Lebenskraft zurückzuerlangen!", sourceObjective = "Pflanzt 4 Samen in lehmiger Erde.", completion = "Algersons Gier mag dem Land geschadet haben, doch noch kann es gerettet werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[48558] = { id = 48558, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Eisenfluträuber", description = "Seht Ihr die mürrischen Kerle in Rot? Das sind die Eisenfluträuber.\n\nDie Schlimmsten der Schlimmsten. Halsabschneider und Plünderer, einer wie der andere.\n\nDie Eisenfluträuber würden die Docks nicht bewachen, wenn sie dabei nichts zu gewinnen hätten...\n\nNehmt ihnen doch ein wenig ihrer Last ab. Mal schauen, was die bei sich haben.", sourceObjective = "Sammelt 3 Azeritentersäbel und 2 Hörner voll Azeritpulver von Halsabschneidern und Kunstschützen der Eisenfluträuber.", progress = "Was habt Ihr gefunden?", completion = "Wie ich mir schon dachte... Die Eisenfluträuber machen mit Aschenwind Geschäfte.\n\nWar ja klar... Gleich und Gleich gesellt sich gern und so weiter.", sourceObjectiveStatus = "unverified-source-field" }
quests[48559] = { id = 48559, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Gabe des Lichts", description = "Ich spüre es. Das ehrenhafte Herz Xe'ras. Ihr unermüdlicher Widerstand gegen die Legion. Möge dies ihr Vermächtnis sein.\n\nMit dem Bau der Vindikaar bedienten wir uns des Netherlichttiegels, um die ungeheuren Kräfte zu nutzen, die ganz Argus durchdringen. Ich glaube, Xe'ras Essenz ist der Schlüssel zu diesem Potenzial.\n\nAber das Licht allein ist nicht genug. Ohne ein Gleichgewicht gibt es keine wahre Harmonie, keinen Zusammenklang.\n\nGebt diese Essenz in den Tiegel, Champion. Das ist der erste Schritt, um die Stärke zu entfesseln, die wir benötigen, um dem Brennenden Kreuzzug ein Ende zu setzen.", sourceObjective = "Bringt die Essenz des Lichts in den Netherlichttiegel ein.", completion = "Ein wichtiger erster Schritt, {name}.\n\nWenn wir im Netherlichttiegel ein Gleichgewicht herstellen, wird Eure Waffe noch mächtiger. Davon bin ich überzeugt.", sourceObjectiveStatus = "unverified-source-field" }
quests[48560] = { id = 48560, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Gabe des Schattens", description = "Spürt Ihr das, {name}? Die Dunkelheit in dieser Essenz ist praktisch greifbar.\n\nFrüher hätte ich mich vor solcher Macht gescheut oder gar ihre Existenz verleugnet. Doch wenn es eins gibt, das wir während unseres langen Konflikts gelernt haben, dann ist es, dass Licht und Schatten nur gemeinsam existieren können.\n\nMöglicherweise ist dies genau, was wir brauchen, um das Gleichgewicht im Netherlichttiegel wiederherzustellen und uns so einen Vorteil gegenüber der Legion zu verschaffen.\n\nErfüllt den Tiegel mit dieser Essenz, Champion. Nähert Euch der Ausschöpfung des wahren Potenzials der Waffe.", sourceObjective = "Erfüllt den Netherlichttiegel mit der Essenz der Schatten.", completion = "Ah ja. Das Gleichgewicht ist der Schlüssel, wie der Prophet schon sagte.", sourceObjectiveStatus = "unverified-source-field" }
quests[48573] = { id = 48573, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krokiliskenleben", description = "Wenn wir Urok töt'n woll'n, brauch ich mein Schamanenmojo zurück! Mein letzter Versuch, ihn zu töt'n, ging gehörig schief.\n\nIhr helft mir, meine Macht zurückzukrieg'n, und ich helf Euch, Urok zu töt'n. Abgemacht?\n\nAls Erstes nehmt Ihr diesen Dolch, um damit alles restliche Leben aus den Krokilisken zu absorbier'n, die Ihr tötet.\n\nWenn der Dolch gesättigt ist, bringt ihn zurück.\n\nHeh heh, genau, Sur'jan, sie helf'n uns. Urok wird schon seh'n, wer der Stärkere is'!", sourceObjective = "Absorbiert Essenz von 8 Urschnappkieferkadavern mit Sur'jans Ritualdolch.", completion = "Ah, sehr gut! Die werd'n für das Ritual reich'n!", sourceObjectiveStatus = "unverified-source-field" }
quests[48574] = { id = 48574, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zähne ziehen", description = "Ich brauch noch mehr Dinge, um stärker zu werd'n. Ihr müsst mir 'n paar Sauridenzähne besorg'n.\n\nNee, Sur'jan, du vertraust <ihm/ihr> nich' ZU sehr. Gerade genug. Wir lass'n uns nicht mehr verrat'n.\n\nIch brauch die Zähne für 'n Ritual, durch das ich meine Macht zurückbekomm'. Wenn ich nich' mehr so schwach bin, werd'n wir beide dieses untote Monster erledig'n.", sourceObjective = "Besorgt 40 Sauridenzähne.", progress = "Habt Ihr genug Zähne gesammelt?", completion = "Wie viele hab'n wir denn... gut! Das reicht.\n\nSchh! Ich hab gesagt, das reicht, und nich', dass wir damit fertig sin'. Nerv mich jetzt nich', Sur'jan!", sourceObjectiveStatus = "unverified-source-field" }
quests[48576] = { id = 48576, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sicherer Flug", description = "Ich fühl mich... stärker! Aber ich brauch immer noch mehr Macht, bevor wir Urok schlag'n könn'.\n\nNein, Sur'jan, DU hast mehr Angst vor Urok als ich. Ich hab vor nichts un' niemand Angst!\n\nNach diesem Ritual seid Ihr mit mir verbund'n. Tötet die Himmelsschreck'n in der Nähe, damit ich noch stärker werd.\n\nNehmt mein' Greifhaken. Damit könnt Ihr sie vom Himmel hol'n un' fertigmach'n.", sourceObjective = "Tötet 8 Urhimmelsschrecken.", completion = "Gut! Ich fühl mich schon stärker. Wir sin' ein super Trio, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[48577] = { id = 48577, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eier abschrecken", description = "Sur'jan, das sollte ich erledig'n! Was soll das heißen, ich soll mich erhol'n? Bah, na gut.\n\nIch brauch noch mehr Macht und die Eier der Himmelsschrecken sin' ganz in der Nähe. Ihr müsst 'n paar ihrer Eier zerstör'n, damit ich noch mehr Energie bekomm'.\n\nIn diesen Eiern steckt 'ne Menge Lebensenergie und wenn Ihr die Eier zerstört, strömt ihre Energie zu mir.\n\nKomm schon, Sur'jan, total einfach, das kann ich auch! Wie bitte? Nun ja, da hast du recht. Du warst schon immer der Schlauere von uns beid'n.", sourceObjective = "Zerstört 5 Himmelsschreckeneier.", completion = "Ich fühl mich schon viel besser! Vielleicht sollt ich ab jetzt mehr von diesen Eiern zerstör'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[48578] = { id = 48578, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Auge auf den Himmelsschrecken", description = "Es gibt 'nen echt groß'n Himmelsschrecken namens Jarkadiax. Ich brauch seine Zunge...\n\nWas denn, Sur'jan? Nich' die Zunge? Das Auge? Sicher? Hrm.\n\nIch brauch sein Auge für das nächste Ritual. Ich weiß, was Ihr denkt. Eine Zunge ergibt viel mehr Sinn, meine ich auch, aber...\n\nHör zu, Sur'jan, ich bin mir sicher, es is' die Zunge. Wir werd'n ja seh'n, wer recht hat!\n\nHolt mir Jarkadiax' Auge für mein nächstes Ritual.", sourceObjective = "Besorgt Jarkadiax' Auge.", progress = "Ich brauch das Auge. Habt Ihr's gefund'n?", completion = "Ihr habt das Auge!\n\nIch spür die Macht, die das Ding ausstrahlt. Könnt Ihr das seh'n?\n\nHalt den Mund, Sur'jan, ich weiß, dass du das seh'n kannst. Ich red aber mit ihm!", sourceObjectiveStatus = "unverified-source-field" }
quests[48581] = { id = 48581, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein paar kräftige Klapse", description = "Wir sperr'n Pinkie erst mal in den Terrorhornpferch, aber die Bestienzähmer werd'n ihre liebe Mühe mit ihm ham!\n\nDa ist eine harte Hand gefordert.\n\nKönnt Ihr ihnen helf'n?", sourceObjective = "Helft den Zähmern, Pinkie zu bändigen.", completion = "Damit habt Ihr Euch im Kral einen Namen gemacht, {name}!\n\nPinkie is' wie für die Schlacht gemacht, wenn er mal groß is', was meint Ihr?", sourceObjectiveStatus = "unverified-source-field" }
quests[48584] = { id = 48584, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Blut meiner Feinde", description = "Meine Macht kehrt zurück! Das reicht aber noch nich'. Wir brauch'n mehr, wenn wir diesen untoten Urok besieg'n woll'n.\n\nWir dring'n in Uroks Höhle vor. In der Gegend wimmelt's von Schreckenszecken. Bringt mir ihr Blut fürs letzte Ritual.\n\nNehmt das hier. Mein verlässliches Schreckenszeckeninsektizid. Werft es einfach irgendwo hin, un' sobald sie daran schnüffeln... MAUSETOT! Hahaha! Jetzt geht!\n\nSur'jan, ständig soll <er/sie> solche Aufgaben übernehm'n, aber ich kann das auch! Na gut, ich bereit mich jetzt aufs Ritual vor.", sourceObjective = "Sammelt 45 Brocken geronnenes Schreckenszeckenblut.", progress = "Habt Ihr schon das Blut für mich?", completion = "Das wird funktionier'n. Bald hab ich meine Macht zurück!", sourceObjectiveStatus = "unverified-source-field" }
quests[48585] = { id = 48585, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überleben in der Ödnis", description = "<Das Leder ist durch die Sonne trocken und rissig geworden, aber der Inhalt scheint weitestgehend intakt geblieben zu sein.\n\nAuf welche grausame Weise der vorherige Besitzer zu Tode gekommen ist, bleibt unbekannt, aber solche Vorräte sind unter den Ausgestoßenen sehr begehrt.\n\nDie Wüste hat viele Opfer gefordert... Vielleicht lassen sich in den Dünen noch mehr Vorräte finden.>", sourceObjective = "Sammelt 10 geplünderte Vorräte.", progress = "Was habt Ihr für mich?", completion = "Ihr habt Euren Sammelausflug wohl überlebt!\n\nDer Stamm kann die Vorräte gut gebrauch'n. Ich dank Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[48588] = { id = 48588, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heilung der Infektion" }
quests[48590] = { id = 48590, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kopf und Schulter", description = "Wenn wir Urok bekämpf'n woll'n, brauch ich meine Ausrüstung zurück. Ich hab sie verlor'n, als wir beim erst'n Mal vor Urok weggerannt sind.\n\nHalt den Mund, Sur'jan! Ich musste das loswerd'n, um schneller renn' zu könn'.\n\nBringt mir meine Ausrüstung zurück, dann könn' wir Urok zusamm' geg'nübertret'n.", sourceObjective = "Bringt Sur'jans Kopf- und Schulterausrüstung zurück.", progress = "Habt Ihr meine Ausrüstung?", completion = "Meine Ausrüstung! Ah, die riecht sogar wie neu. Habt Ihr sie sauber gemacht?", sourceObjectiveStatus = "unverified-source-field" }
quests[48591] = { id = 48591, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uroks wahrer Tod", description = "Es is' getan! Meine Macht is' zurück! Jetzt geht's Urok an den Kragen. Er war einst so 'n stolzes und prächtiges Tier, wisst Ihr?\n\nJetzt is' er nur noch 'n seelenloser Untoter. Das darf nich' sein. Wir schenk'n ihm seine ewige Ruhe.\n\nIch renn voraus. Wenn Ihr in seine Nähe kommt, spring ich aus meinem Versteck und greif an. Los geht's!\n\nKlappe, Sur'jan! Natürlich werd'n wir gewinnen! Und wenn nich', muss eben <ein anderer/eine andere:c> {class} her, <der/die:c> uns hilft.", sourceObjective = "Besiegt Urok.", completion = "Wir haben's geschafft! Urok is' Geschichte. Es tut mir leid, dass er so end'n musste, aber so 'ne Kreatur darf nich' existier'n.\n\nIch hab noch Einiges mehr zu tun. Zum Beispiel die zwei anderen Trolle find'n und töt'n.\n\nWas meinst du, Sur'jan? Soll ich es ihm sagen? Nein? Okay, na gut.\n\nBis bald! Und bleibt nich' zu lange in Nazmir. Hier gibt's nur Verrückte.", sourceObjectiveStatus = "unverified-source-field" }
quests[48592] = { id = 48592, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Spitze halten" }
quests[48597] = { id = 48597, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sauroliskenflucht", description = "Ihr nähert Euch achtsam dem angebundenen Saurolisken. Er versucht nicht, Euch zu beißen, sondern sieht Euch mit einem Blick an, der seine Resignation zum Ausdruck bringt.\n\nDie Troggs halten diese Saurolisken wohl gegen ihren Willen. Man sollte sie befreien, bevor sie noch weiter misshandelt werden.", sourceObjective = "Befreit 6 gefangene Saurolisken.", completion = "Troggs trainieren Saurolisken als Reittiere? Da haben sie wohl von unserem Beispiel gelernt.\n\nEs ist gut, dass Ihr sie befreit habt. Ich möchte mir nicht ausmalen, was passieren würde, wenn sich das Reiten bei den Troggs durchsetzen würde!", sourceObjectiveStatus = "unverified-source-field" }
quests[48600] = { id = 48600, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Etwas weniger Druck", description = "Die Dämonen, die aus Antorus strömen, rüsten sich in der Teufelsfeuerwaffenkammer aus. Wir müssen ihnen die Waffen verwehren. Könnt Ihr als {class} Eure Ordensmitglieder davon überzeugen, erneut an der Seite der Armee des Lichts zu kämpfen?\n\nSammelt vor dem Angriff Materialien. Meine Schmiede werden Euren Soldaten mächtigere Rüstung verschaffen. Die Legion wird das Teufelsfeuer nicht ohne Kampf aufgeben.", sourceObjective = "Bringt 6 Champions auf Gegenstandsstufe 950.", completion = "Ein weiterer Schritt zum Sieg über die Legion.", sourceObjectiveStatus = "unverified-source-field" }
quests[48601] = { id = 48601, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teufelsfeuerzerschmetterung", description = "Eine dünne Reihe von Steinbrücken verbindet den Brennenden Durchbruch mit der Teufelsfeuerwaffenkammer am Scheusalslauf. Die Armee des Lichts wird die Verstärkung der Legion eindämmen, während unsere Leute sich um die Waffenkammer kümmern.\n\nMacht schnell.", sourceObjective = "Benutzt die Späherkarte und schließt die Mission \"Angriff auf die Teufelsfeuerwaffenkammer\" ab.", completion = "Es gibt nichts Schöneres, als die Explosion eines Lichtimpulssprengsatzes in einer Legionsfestung. Eure Leute haben gute Arbeit geleistet.", sourceObjectiveStatus = "unverified-source-field" }
quests[48604] = { id = 48604, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Endlich wieder zu Hause", description = "Für Eure Hilfe kann ich Euch wirklich nicht genug danken! Ihr kamt gerade rechtzeitig.\n\nHier ist Elias' Würstchenbestellung. Keine Sorge, das sind ganz normale leckere Würstchen, nichts Ungewöhnliches.\n\nJetzt entschuldigt mich bitte, ich muss nach meiner Belegschaft schauen.", sourceObjective = "Kehrt zu Elias Eimann in Fallhafen zurück.\n\nBereitgestellter Gegenstand:", sourceObjectiveStatus = "unverified-source-field" }
quests[48605] = { id = 48605, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ende des Kommandanten", description = "Champions der Legion sind innerhalb eines Invasionspunkts besonders verwundbar! Findet einen von ihnen und vernichtet ihn, bevor er nach Argus zurückkehren kann.", sourceObjective = "Schließt das Szenario eines großen Invasionspunkts ab.", completion = "Ihre Kommandanten sind dem Tode geweiht!", sourceObjectiveStatus = "unverified-source-field" }
quests[48606] = { id = 48606, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geladen und bereit", description = "<Diese glitzernde Kanonenkugel ist auffälliger als die anderen. Ihr bemerkt den bekannten Glanz von Azerit auf ihrer Oberfläche.\n\nUnd zufällig bemerkt Ihr in der Nähe eine Kanone, die praktischerweise auf die mit Waffen beladenen Schiffe von Aschenwind & Co. gerichtet ist.>", sourceObjective = "Benutzt die Aschenwindkanone, um 6 Vorräte von Aschenwind & Co. zu vernichten. Zum Feuern der Kanone werden Azeritkanonenkugeln benötigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[48614] = { id = 48614, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leidvolle Folgen" }
quests[48615] = { id = 48615, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krieg bleibt immer gleich" }
quests[48616] = { id = 48616, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bolas und Vögel", description = "Oben in den Bergen erkennt man den Wert eines guten Jagdbegleiters. Wir schießen unsere fliegende Beute mit Bolas ab und die Retriever bringen sie uns zurück!\n\nWollt Ihr es mal versuchen? Nickel kann Euch dabei begleiten. Holt im Wald einen der Falken aus der Luft. Mein Hund wird den Rest übernehmen.", sourceObjective = "Schießt 6 Hohlschnabelfalken mit dem Bolawerfer ab.", completion = "Es gibt nichts Besseres als die Zusammenarbeit von Mensch und Tier auf der Jagd.", sourceObjectiveStatus = "unverified-source-field" }
quests[48620] = { id = 48620, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großer Invasionspunkt: Herrin Alluradel" }
quests[48622] = { id = 48622, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der verschwundene Fürst", description = "Wir verfügen leider über keine Kontakte im Haus Kronsteig, also müssen wir in Drustvar wohl von ganz unten anfangen.\n\nEine Fähre wird Euch nach Fallhafen bringen. Das ist ein Bauerndorf im Osten von Drustvar. Cyril Weiß, der dortige Bürgermeister, ist ein langjähriger Freund der Prachtmeers. Er kann uns bestimmt mit jemandem von Haus Kronsteig in Kontakt bringen.\n\nIch hoffe, Ihr findet den Grund für ihr Verschwinden heraus, {name}. Wir brauchen ihre Kampfkraft unbedingt in der Flotte von Kul Tiras.", sourceObjective = "Trefft Cyril Weiß in Fallhafen in Drustvar.", completion = "<Das Bildnis ist durch mächtige Magie geschützt.\n\nMit roher Gewalt kann der Fluch wohl nicht gebrochen werden.>", sourceObjectiveStatus = "unverified-source-field" }
quests[48624] = { id = 48624, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wer hat die von der Leine gelassen?" }
quests[48634] = { id = 48634, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weitere Vorräte für Krokuun", description = "Dieser unwirtliche Ort hat meinen Leuten nicht viel zu bieten. Wir verbringen fast die gesamte Zeit damit, Dinge zum Überleben zusammenzukratzen. Wenn ich mehr Vorräte hätte, könnte ich Euch einen weiteren Gratpirscher anbieten.\n\nWas meint Ihr, <Außerweltler/Außerweltlerin>?", sourceObjective = "Sammelt 900 Ordensressourcen.", progress = "Braucht Ihr die Hilfe eines weiteren Gratpirschers?", completion = "Ihr müsst unsere Hilfe wirklich wertschätzen, wenn Ihr Euch von solch einer Beute trennt.", sourceObjectiveStatus = "unverified-source-field" }
quests[48635] = { id = 48635, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erweiterte Leerenimpfung", description = "Alle, die vom Schatten berührt worden sind, hinterlassen bei ihrem Ableben Spuren der Leere. Wenn Ihr bei Euren Reisen in die Stadt genug davon einsammeln könnt und dann zu mir zurückkehrt, werde ich ein besonders reines Destillat daraus herstellen. \n\nWir können noch mehr von meinen Leuten retten.", sourceObjective = "Sammelt 100 Fragmente kondensierter Leere.", progress = "Der Schatten hat sich bei vielen meiner Brüder tief eingenistet. Es wird äußerst schwierig werden, sie zu befreien. Werdet Ihr mir helfen?", completion = "Eure Großzügigkeit beschämt mich.", sourceObjectiveStatus = "unverified-source-field" }
quests[48636] = { id = 48636, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versorgung des antorischen Feldzugs", description = "Zur Versorgung ihrer Kreuzzüge benötigt die Legion Rohmaterial von den eroberten Welten. Durchdringt die Legionsportale, vernichtet jeden Dämon, den Ihr findet, und haltet sie davon ab, ihre Kriegsmaschine mit Materialien zu versorgen.", sourceObjective = "Schließt 10 Invasionspunkte ab.", progress = "Der Krieg ist kostspielig. Habt Ihr weitere Vorräte für unsere Bemühungen gesammelt?", completion = "Noch ein Lichtgeschmiedeter kämpft an Eurer Seite.", sourceObjectiveStatus = "unverified-source-field" }
quests[48637] = { id = 48637, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Läuterndes Feuer" }
quests[48639] = { id = 48639, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Armee des Lichts", description = "Unterstützt die Armee des Lichts, indem Ihr 4 Weltquests abschließt.", sourceObjective = "Schließt 4 Weltquests für die Armee des Lichts auf Argus ab.", completion = "Die Armee des Lichts dankt Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[48640] = { id = 48640, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das unsterbliche Geschwader" }
quests[48641] = { id = 48641, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Legionsrichter", description = "Unterstützt die Legionsrichter, indem Ihr 4 Weltquests abschließt.", sourceObjective = "Schließt 4 beliebige Weltquests an der Verheerten Küste ab.", progress = "Kehrt zu mir zurück, wenn Ihr Eure Unterstützung der Legionsrichter abgeschlossen habt, {name}.", completion = "Die Legionsrichter danken Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[48642] = { id = 48642, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Argusvorstoß", description = "Unterstützt den Argusvorstoß, indem Ihr 4 Weltquests abschließt.", sourceObjective = "Schließt 4 Weltquests für den Argusvorstoß auf Argus ab.", completion = "Der Argusvorstoß dankt Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[48653] = { id = 48653, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein juwelenbesetztes Gefängnis", description = "<Während Ihr in die Tiefen des merkwürdigen Juwels blickt, verspürt Ihr plötzlich ein seltsames Verlangen danach, in die Sümpfe von Nazmir zu reisen und das Juwel an seinen rechtmäßigen Platz zu bringen. Wo auch immer der ist.>", sourceObjective = "Bringt das wiederhergestellte Auge der Ewigkeit zurück an seinen Platz im Schreckenssumpf.", sourceObjectiveStatus = "unverified-source-field" }
quests[48654] = { id = 48654, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unterhalb von Oronaar", description = "Der Krokul, den wir unterhalb von Oronaar gefunden haben, hat sich geweigert, von dort wegzugehen. {name}, könntet Ihr vielleicht mit ihm sprechen und ihn überzeugen an Bord der Vindikaar zu gehen?", sourceObjective = "Sprecht mit dem Krokul unterhalb von Oronaar.", completion = "Ich habe es den anderen schon gesagt: Ich werde meine Leute nicht im Stich lassen. Ich muss hierbleiben. Aber vielleicht könnt Ihr mir helfen. Ich habe eine Möglichkeit gefunden, die Leerenverseuchten von dem Schatten zu befreien.", sourceObjectiveStatus = "unverified-source-field" }
quests[48655] = { id = 48655, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Lehrling des Kochs", description = "<Sezahjin durchwühlt frustriert seine Kochzutaten.>\n\nWo is' Junji? Ich hab ihn losgeschickt, um Geiereier zu hol'n, aber er is' immer noch nich' zurück.\n\n<Sezahjin hält einen Moment lang inne.>\n\nEr hat was über die Größe der Sauroliskeneier gesagt, aber diese riesigen Echsen sin' viel zu gefährlich für 'n Jungen! So blöd kann doch nich' mal er sein...\n\nWenn er zum Brutbereich der Saurolisken gegang'n is', is' er vielleicht schon tot. Geht ihn bitte such'n, bevor's zu spät is'!", sourceObjective = "Findet Junji.", completion = "Von so 'nem Saurolisken lass ich mich nich' reinleg'n! Ich weiß, dass du da drauß'n bist un' mich fress'n willst! Oh, verzeiht... Ihr seid ja ein Erwachsener! Bitte, holt mich hier raus! Hilfe!", sourceObjectiveStatus = "unverified-source-field" }
quests[48656] = { id = 48656, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wilde Saurolisken", description = "Bitte helft mir! Ich steck hier fest un' komm allein nich' raus!\n\nIch wollt hier Eier sammeln. Ich wusst ja, dass das keine gute Idee is', aber ich dacht, ich könnt die Saurolisken austricksen un' die Eier wegschnapp'n.\n\nHat nich' geklappt...\n\nDie wollt'n mich fress'n, da hab ich mich unter der Kiste versteckt!\n\nKönntet Ihr vielleicht die Saurolisken ausschalt'n un' mir Bescheid sag'n, wenn ich sicher rauskomm' kann?\n\nBitte lasst mich hier nich' zurück!", sourceObjective = "Tötet 8 Schuppenklauensaurolisken im Verdorrten Becken.", completion = "Die Saurolisken sin' alle weg un' ich kann sicher rauskomm'n? Ich dank Euch! Ich dacht, ich komm hier nich' lebend raus!", sourceObjectiveStatus = "unverified-source-field" }
quests[48657] = { id = 48657, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Möglicherweise lecker", description = "Sauroliskeneier sin' die leckersten Eier in der ganzen Wüste!\n\nIch... hab sie zwar noch nie selber probiert, aber schaut doch nur mal, wie groß die sin'! Die sin' riesig, un' je größer, desto besser, oder?\n\nWenn ich mit leeren Händen ins Lager zurückkomm, bringt Sezahjin mich um! Wir müss'n 'n paar von den Eiern einsamm'ln!\n\nIhr klingt viel älter und stärker als ich. Holt die Eier, damit alle genug zu ess'n krieg'n.\n\nUn' macht Euch nur keine Sorgen um mich. Ich wart einfach hier und rühr mich nich' vom Fleck...", sourceObjective = "Sammelt 10 Sauroliskeneier im Verdorrten Becken.", progress = "Habt Ihr die Sauroliskeneier?", completion = "Ihr habt die Eier! Seid vorsichtig un' macht sie nich' kaputt... Rollt sie ganz, ganz sachte unter die Kiste...", sourceObjectiveStatus = "unverified-source-field" }
quests[48662] = { id = 48662, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kurze Lunten" }
quests[48668] = { id = 48668, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lichtgeschmiedetes Signal: Stadtzentrum", description = "Seid gegrüßt!\n\nHauptmann Fareeya hat uns vorausgeschickt, um dieses Gebiet zu sichern. Wir wollten gerade ein Signal anfordern und uns auf der Vindikaar zurückmelden.\n\nEs wäre uns eine Ehre, wenn Ihr uns helfen könntet, die Mission zu erfüllen.\n\nDas Signal braucht nur einen kleiner Stupser. Der Großkonstrukteur kümmert sich dann um den Rest.", sourceObjective = "Aktiviert das Signalfeuer der Vindikaar.", completion = "Dieses Signal wird der Navigationskonsole hinzugefügt.\n\nEine Einheit der Armee des Lichts wird zurückbleiben, um diesen Standort für zukünftige Einsätze zu sichern.", sourceObjectiveStatus = "unverified-source-field" }
quests[48669] = { id = 48669, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urok, Schrecken des Sumpflands", description = "Ihr! Ihr könnt mir helf'n!\n\nIch weiß, Sur'jan, <er/sie> mag zwar wie <'n/'ne:c> {class} ausseh'n, aber wir können <ihm/ihr> trau'n. Ich weiß es.\n\nUrok, der Schrecken des Sumpflands, is' jetzt 'n Untoter. Wir müss'n ihn aufhalt'n, bevor er hier alles zerstört.\n\nWartet nur kurz und Ihr seht, wozu Urok in der Lage ist.\n\nSchhh, Sur'jan, sie werden versteh'n, bald werden sie alle versteh'n!", sourceObjective = "Trefft Urok, den Schrecken des Sumpflands.", completion = "Versteht Ihr jetzt? Urok muss besiegt werd'n! Ich weiß auch schon wie, aber ich brauch Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[48670] = { id = 48670, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fluchtreiter", description = "Lord Norwinsen forderte mich auf, mit Emil in den Wald zu reiten. Ich wusste, dass es noch zu früh ist! Ich wusste es einfach!\n\nWir müssen ihn finden. Trefft mich drüben auf der anderen Seite des Flusses!", sourceObjective = "Trefft Marina Kenner nahe der Nebelhauchkluft.", completion = "Wie konnte das denn noch schlimmer werden?\n\nDie Troggs haben Emil geschnappt!", sourceObjectiveStatus = "unverified-source-field" }
