quests[48676] = { id = 48676, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lockout Tracking - Normal - Forest" }
quests[48677] = { id = 48677, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weidenverehrung", description = "Seid gegrüßt, <Reisender/Reisende>! Ihr seht aus, als könntet Ihr mir aus meiner misslichen Lage helfen!\n\nEs geht um Edwin, meinen Sohn. Als wir auf unserem Weg durch Drustvar haltmachten, um unsere Waren anzubieten, nahm der verfluchte Narr Reißaus und schloss sich irgendeinem Kult hier im Herbsttal an! Seither ist er verschwunden und diese Verrückten in ihren braunen Roben verraten mir nicht, wo er ist!\n\nKönnt Ihr sie vielleicht zum Reden bringen? Seine arme Mutter ist krank vor Sorge!", sourceObjective = "Trefft Lord Herbsttal im Herbsttal.", completion = "Was führt Euch in unser Tal, {class}?", sourceObjectiveStatus = "unverified-source-field" }
quests[48678] = { id = 48678, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fragwürdige Opfergaben", description = "Die Händler haben Euch geschickt? Ich habe ihnen bereits gesagt, dass ich die Belange meiner Familie nur mit jenen bespreche, die unsere Sache verstehen.\n\nWenn Ihr wissen wollt, wo er ist, müsst Ihr beweisen, dass Ihr dazugehört.\n\nHinter uns findet Ihr Gegenstände, die dem Weidenmann als Opfer dargebracht werden sollen. Bringt uns die Opfergaben, die Eurer Meinung nach dem Weidenmann am besten gefallen würden, sodass er uns vielleicht seinen Segen gewährt.\n\nWählt die korrekten Gegenstände aus und erweist Euch als würdig.", sourceObjective = "Bringt die richtigen Opfergaben zum Weidenmann im Herbsttal.", progress = "Ihr müsst die richtigen Opfergaben bringen, wenn Ihr Euer Verständnis unter Beweis stellen wollt.", completion = "Eure Opfer haben dem Weidenmann gefallen. \n\nNun gut, stellt Eure Fragen, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[48679] = { id = 48679, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorsicht vor dem Schwarm", description = "Dieser Edwin kam vor Kurzem zu uns und suchte nach dem Segen des Weidenmanns. Er ging allein in die Hügel und suchte nach möglichen Opfergaben.\n\nDabei störte er unglücklicherweise die Bienenstöcke in der Nähe, was die Bienen ziemlich wütend gemacht hat.\n\nDanach habe ich ihn nicht mehr gesehen.", sourceObjective = "Findet Edwin Maldus im Dornstacheltal.", completion = "Ihr habt nach Edwin gesucht, richtig?\n\nIhr müsst ihm helfen!", sourceObjectiveStatus = "unverified-source-field" }
quests[48680] = { id = 48680, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht die Bienen!" }
quests[48682] = { id = 48682, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein einfaches Opfer", description = "Beeilt Euch! Lord Herbsttal hat Edwin in diese Höhle verfrachtet, als er zurückkam. Er sprach von einem Blutopfer!\n\nAnscheinend wollen sie ihn dem Weidenmann als Opfer darbringen!\n\nWas ist das für ein wahnsinniger Kult?", sourceObjective = "Rettet Edwin Maldus vor den Kultisten der Weidenjünger im Herbsttal.", progress = "Helft mir!", completion = "Diese Kultisten wollten mich töten!\n\nIch weiß ja nicht, was Ihr davon haltet, aber für mich reicht es jetzt mit diesem Weidenmann!", sourceObjectiveStatus = "unverified-source-field" }
quests[48683] = { id = 48683, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wechselnde Jahreszeiten", description = "Danke, dass Ihr mich schon wieder gerettet habt. Wir müssen verhindern, dass es anderen so ergeht wie mir.\n\nSo lange dieser Weidenmann steht, wird er nur noch mehr Unheil verursachen.\n\nWir müssen ihn zerstören! Helft Ihr mir?", sourceObjective = "Verbrennt den Weidenmann im Herbsttal.", progress = "Der Weidenmann muss zerstört werden!", completion = "Das war wahrlich eine Lektion für mich.\n\nDanke, mein Freund. Ich kehre jetzt mit meinen Eltern nach Boralus zurück.\n\nHier, nehmt das für Eure Mühen.", sourceObjectiveStatus = "unverified-source-field" }
quests[48684] = { id = 48684, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unterwegs", description = "Joraks Wunden sin' so weit verheilt, dass er reis'n kann.\n\nEr is' einverstanden, uns zum Tempel zu bring'n. \n\nJe früher wir aufbrech'n, desto besser. Rakera wird nich' lange in der Wüste überleb'n.", sourceObjective = "Reist mit Meerahs Wagen, um nach Kriegswache Rakera zu suchen.", completion = "Dieser Tempel is' nich' so, wie ich ihn mir vorgestellt hab.", sourceObjectiveStatus = "unverified-source-field" }
