quests[48698] = { id = 48698, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kaara die Bleiche" }
quests[48699] = { id = 48699, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heimlich nach Zalamar", description = "Ihr denkt jetzt bestimmt, dass sich doch gar nix verändert hat, aber vertraut drauf, dass meine Voodoozauber gewirkt ham. Glaub ich.\n\nSobald Ihr Euch Zalamar nähert, verwandelt Ihr Euch in 'nen Bluttroll.\n\nJo'chunga werdet Ihr dort find'n, wo sich viele Bluttrolle versammelt ham.\n\nFindet Jo'chunga und sagt ihm, dass ich Euch geschickt hab. Er wird Euch dann erzähl'n, wie die Situation vor Ort ist.", sourceObjective = "Schleicht Euch nach Zalamar hinein und findet Jo'chunga.", completion = "Hier drin sin' wir sicher. Zum Glück seid Ihr hier. Allein kann ich das nich' aufhalt'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[48701] = { id = 48701, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baruut der Blutrünstige" }
quests[48715] = { id = 48715, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Akunda erwartet Euch", description = "Ich hab mit allen Trollen hier gesproch'n un' nach Rakera gefragt. Un' wie Ihr Euch vielleicht schon gedacht habt, kenn' die nur den Namen \"Akunda\". \n\nWir müss'n hoff'n, dass uns jemand im Tempel was erzähl'n kann.", sourceObjective = "Untersucht den Tempel von Akunda.", completion = "Das is' Rakera. Kein Zweifel. Aber aus irgend'nem Grund erinnert die sich nich' an mich. Un' wohl auch nich' an sich selbst...", sourceObjectiveStatus = "unverified-source-field" }
quests[48722] = { id = 48722, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fiesel der Muffindieb" }
