quests[48740] = { id = 48740, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skreeg der Verschlinger" }
quests[48752] = { id = 48752, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kohleknappheit", description = "Ah! {name}! Genau die Person, auf die ich gehofft hatte!\n\nIch wollte gerade ein bisschen Monelit zu Barren verhütten. Dann habe ich aber bemerkt, dass mein Kohlevorrat langsam zur Neige geht.\n\nAlso... natürlich habe ich noch Kohle, aber ich bevorzuge Kohle von Aschenwind. Die produziert weniger Rauch und brennt mit höherer Temperatur. Ich brauche also weniger für das gleiche Ergebnis.\n\nIhr bekommt die Aschenwindkohle in der Aschenwindgießerei südlich von hier. Wenn Ihr das übernehmt, gebe ich Euch gerne ein paar wertvolle Tipps, wie Ihr Monelit effektiver abbauen könnt. Sind wir im Geschäft?", sourceObjective = "Sammelt 9 Handvoll Kohle von Aschenwind.", progress = "Wart Ihr schon in der Gießerei?", completion = "Danke! Jedes Detail ist wichtig, wenn es um dicke Rauchwolken von brennender Kohle und geschmolzenem Metall geht.\n\nIch schulde Euch eine Lektion über Monelit. Mal sehen, was ich Euch noch beibringen kann...\n\nWenn Ihr Monelit abbaut, haut nicht einfach grob den Fels weg, sondern versucht, mit der Spitzhacke das Metall zu durchbohren und dann das ganze Stück vorsichtig wie Gummi vom Felsen wegzuziehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[48753] = { id = 48753, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Notfallverpflanzung", description = "Neben allem, was drüben in Drustvar geschieht, haben sich auch noch die Tiere im Sund stark vermehrt. Normalerweise wäre mir das egal, aber sie haben fast alle Flussknospen aufgefressen!\n\nWenn sich das nicht bald von selbst bessert, könnten wir versuchen, ihre Zahl ein wenig einzudämmen, damit sie nicht auch den letzten Rest fressen. Aber das wäre für mich nur der letzte Ausweg.\n\nKönntet Ihr stattdessen ein paar dieser Samen ausbringen, um sie mit zusätzlichem Futter zu versorgen?", sourceObjective = "Pflanzt 10 Flussknospensamen im Flussschlamm.", completion = "Ich kann Euch nicht genug danken! Flussknospen sind für die Tierwelt hier unerlässlich. Wie auch immer, ich habe gesagt, dass ich Euch etwas beibringe, wenn Ihr helft, und ich werde immer zu meinem Wort stehen.\n\nDer größte Fehler, den die meisten Kräuterkundigen hier draußen begehen, besteht darin, dass sie die Flussknospen beim Ernten auslaufen lassen.\n\nWenn Ihr Flussknospen pflückt, dürft Ihr sie nicht einfach vom Stängel reißen, weil sonst das ganze Wasser herausläuft. Stattdessen solltet Ihr sie drehen, damit sie die Stängel zusammendrücken. Versucht es einmal!", sourceObjectiveStatus = "unverified-source-field" }
quests[48754] = { id = 48754, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Nahrungskette durchbrechen", description = "Die zusätzlichen Flussknospen, die Ihr angepflanzt habt, haben geholfen, aber es reicht nicht. Einige der hiesigen Tiere fressen die Flussknospen, bevor sie reif sind. Je mehr von ihnen weggefressen werden, desto weniger bleiben für uns.\n\nVor allem die Schildkröten scheinen die jungen Flussknospen zu fressen.\n\nWenn die Flussknospen auszusterben drohen, müssen wir ihren Konsum beschränken. Daher solltet Ihr die Anzahl der Schildkröten in der Gegend dezimieren.\n\nWenn Ihr das macht, bringe ich Euch alles bei, was ich über die Flussknospe weiß.", sourceObjective = "Tötet 15 Süßwasserschnapper.", completion = "Gute Arbeit, {name}. Jetzt, da die Schildkröten nicht mehr all unsere kostbaren Flussknospen verschlingen, kann ich endlich wieder ruhig schlafen.\n\nWenn ich mich recht erinnere, habe ich als Dank für Euren Einsatz angeboten, Euch etwas über das effektive Sammeln von Flussknospen zu erzählen.\n\nAlso, das Geheimnis der Flussknospen ist, dass sie in den Wurzeln ein paar zusätzliche Knollen haben. Ihr müsst sie mit gleichbleibend festem Druck an der Windung packen.", sourceObjectiveStatus = "unverified-source-field" }
quests[48755] = { id = 48755, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pollen auf die Hand", description = "Ich glaube, dass irgendeine Kreatur die ganzen Pollen mit seiner Zunge aufgenommen hat.\n\nIch würde zwar gern wissen, was das für eine Kreatur ist, aber es macht eigentlich keinen Unterschied. Ich glaube, wir können das ohne den Einsatz seltener oder gefährlicher Reagenzien nachbilden.\n\nWenn Ihr wieder mal einen Sirenendorn findet, dann feuchtet einfach Euren Handschuh an, damit die Pollen daran kleben bleiben. Ob mit Wasser, Wein oder Speichel... Es sollte in jedem Fall funktionieren.Ihr erlernt:", sourceObjective = "Sammelt 12 gehäufte Handvoll feuchte Pollen von Sirenendorn.", sourceObjectiveStatus = "unverified-source-field" }
quests[48756] = { id = 48756, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Geiste dabei", description = "He, {name}, was haltet Ihr davon, im Gegenzug für einen Gefallen etwas Laufarbeit für mich zu erledigen?\n\nWir haben hier in Kul Tiras eine Tradition, dass bei jeder Feier, ob Beerdigung, Hochzeit oder Geburtstag, Sternmoos zur Dekoration gehört. Das machen wir, damit diejenigen, die nicht mehr unter uns weilen, im Geiste dabei sein können.\n\nWegen der kürzlichen Kämpfe und der immer häufigeren Beerdigungen ist mein Vorrat an Sternmoos fast aufgebraucht.\n\nWenn Ihr mir frisches Sternmoos zur Aufstockung meines Vorrats bringt, verrate ich Euch mein Geheimnis, wie man den Ernteertrag bei jedem Sternmoos steigert.", sourceObjective = "Erntet 10 Stücke frisches Sternmoos.", progress = "Es gab kürzlich schon wieder eine Beerdigung. Sie scheinen sich in letzter Zeit zu häufen. Konntet Ihr das Sternmoos sammeln, um das ich Euch gebeten hatte?", completion = "Ich weiß Euren Einsatz zu würdigen, {name}. Es war schwierig für mich, loszuziehen und selbst etwas zu finden, und der Krieg macht ja auch keine Pause.\n\nUnd jetzt will ich Euch einen Gefallen tun und Euch etwas über das Sammeln von Sternmoos erzählen, das niemand sonst weiß.\n\nEs ist nämlich so, dass die Magie des Sternmooses auf Emotionen reagiert. Fokussiert beim Sammeln Eure Gedanken auf jene, die Ihr verloren habt. Dieses Gefühl von Verlust, Andacht und Freude, die sie uns einst gemacht haben, verhindert, dass die Blumen verwelken. Darum verwenden wir sie für die Feierlichkeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[48757] = { id = 48757, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geistige Beruhigung", description = "Ich bitte Euch nur sehr ungern darum, aber wäret Ihr noch einmal bereit, Euch noch ein bisschen mehr die Hände schmutzig zu machen? Ich würde es ja selbst tun, aber das übersteigt meine Fähigkeiten.\n\nErinnert Ihr Euch, dass ich sagte, wir verwenden Sternmoos, damit diejenigen, die nicht mehr leben, an einem besonderen Tag bei uns sein können?\n\nTja, und manchmal tauchen sie also auf und wollen dann nicht mehr gehen. Es gibt einen Geist im Jenseits, der um sich schlägt und diejenigen verletzt, die er schützen sollte.\n\nNehmt dieses glimmende Sternmoos und läutert den Bereich, bis Ihr den Angreifer findet, und helft ihm, weiterzuziehen.", sourceObjective = "Bringt den wütenden Geist zur Ruhe.", completion = "Ich weiß gar nicht, wie ich Euch danken soll, {name}. Ich werde gleich die Familie davon unterrichten, dass der Geist zur Ruhe gekommen ist, damit sie ihr normales Leben wieder aufnehmen kann.\n\nIhr habt bewiesen, dass ich mich auf Euch verlassen kann. Wenn Ihr schwört, es nicht weiterzuerzählen, verrate ich Euch das größte Geheimnis über Sternmoos.\n\nEs klingt verrückt, aber Ihr müsst es einfach ausprobieren. Damit es der Pflanze gutgeht, müsst Ihr mit ihr sprechen, singen, summen oder auf andere Weise kommunizieren. Ich weiß nicht warum, aber nachdem ich damit angefangen habe, sind vor meinen Augen ein oder zwei neue Blüten entstanden!", sourceObjectiveStatus = "unverified-source-field" }
quests[48758] = { id = 48758, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Widerlich feuchte Blume", description = "Ihr sammelt weiter fleißig Pollen ein und nutzt die Technik, die Ihr von den Bienen gelernt habt. Als Ihr dann allerdings die Hand von der Blume wegzieht, seht Ihr trotzdem keine Pollen an Euren Handschuhen.\n\nIhr schaut genau im Wirbel der Blütenblätter nach, und obwohl es eine erwachsene Pflanze ist, seht Ihr überhaupt keine Pollen. Nach näherer Untersuchung bemerkt Ihr eine zähe Flüssigkeit in der Blume. Stammt sie von der Blume selbst?\n\nVorsichtig pflückt Ihr die Pflanze, was Euch einiges Unbehagen bereitet, um sie Derick zu zeigen.", sourceObjective = "Bringt die widerlich feuchte Blume zu Derick Segler.\n\nBereitgestellter Gegenstand:", completion = "Seltsam. Überhaupt keine Pollen? Das habe ich noch nie von einer Pflanze gehört.\n\nHmmmmmmmmmmm...\n\nIch glaube, wir haben hier eine effektivere Erntemethode für Pollen als die der Bienen.", sourceObjectiveStatus = "unverified-source-field" }
quests[48759] = { id = 48759, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Akundas Biss - Rang 2 freischalten", description = "Fasziniert, dass etwas so Reines weiterhin auf diesem Planeten gedeihen kann, pflückt Ihr die Pflanze. Ihr verspürt eine schwache Macht, die kurz von ihr ausgeht und dann verschwindet.\n\nAls sie in Euren Händen zerfällt, fragt Ihr Euch, ob es an diesem vom Licht verlassenen Ort wohl jemanden gibt, der weiß, wie man mit diesem wertvollen Kraut umgeht.Ihr erlernt:", sourceObjective = "Findet auf Argus jemanden, der Euch beibringen kann, wie Ihr Astralwinden ernten könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[48760] = { id = 48760, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Akundas Biss - Rang 3 freischalten", description = "Fasziniert, dass etwas so Reines weiterhin auf diesem Planeten gedeihen kann, pflückt Ihr die Pflanze. Ihr verspürt eine schwache Macht, die kurz von ihr ausgeht und dann verschwindet.\n\nAls sie in Euren Händen zerfällt, fragt Ihr Euch, ob es an diesem vom Licht verlassenen Ort wohl jemanden gibt, der weiß, wie man mit diesem wertvollen Kraut umgeht.Ihr erlernt:", sourceObjective = "Findet auf Argus jemanden, der Euch beibringen kann, wie Ihr Astralwinden ernten könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[48761] = { id = 48761, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spinnenphobie", description = "Der Kampf gegen Monster ist Euch nicht fremd, nicht wahr?\n\nVor ein paar Tagen habe ich diese Spinne vor meinem Haus gesehen. Nichts Besonderes, außer dass sie so groß war, WIE EIN PFERD.\n\nNach einer halben Stunde Geschrei und Gekloppe mit der Spitzhacke hatte ich sie endlich erledigt.\n\nIch habe mit ein paar Wachen gesprochen und die meinten, dass es ein riesiges Nest dieser Spinnen über den Hügel im Nordwesten gibt.\n\nWenn Ihr sie tötet oder vertreibt, dann erkläre ich Euch einen geheimen Trick beim Abbau von Monelit. Ansonsten muss ich wohl von hier wegziehen.", sourceObjective = "Tötet 8 bezauberte Mooszähne und zerstört 15 Mosszahneier.", completion = "Ich bin froh, dass Ihr es in einem Stück zurückgeschafft habt. Ich würde Euch ja gerne fragen, wie es gelaufen ist, aber nur darüber nachzudenken, hat mir schon genug Alpträume bereitet.\n\nWenn es Euch nichts ausmacht, lenke ich mich ein wenig von dem Gedanken ab, indem ich Euch eine Lektion erteile.\n\nIhr habt sicher schon bemerkt, dass Monelit sehr leicht formbar ist. Diese Eigenschaft müsst Ihr ausnutzen, noch bevor Ihr es verhüttet.\n\nWenn Ihr mit Eurer Spitzhacke das Metall verformt, wenn es noch in der Ader ist, könnt Ihr es erhitzen und mit der anderen Technik, die ich Euch gezeigt habe, ein noch größeres Stück herausholen.", sourceObjectiveStatus = "unverified-source-field" }
quests[48762] = { id = 48762, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rendezvous mit Duftblüte", description = "Ihr scheint Euch mit den Pflanzen hier vertraut gemacht zu haben. Es gibt da eine Blume, die in den schneereichen Gebieten des Kontinents wächst, aber ich weiß nicht allzu viel darüber. Ich kann die Kälte nicht ausstehen.\n\nWenn Ihr aber mehr darüber erfahren wollt, kenne ich jemanden, der Euch weiterhelfen kann.\n\nIhr Name ist Xun Xun Duftblüte und ich habe gehört, dass sie sich jetzt in Jederhafen in Drustvar aufhält. Aber passt auf Euch auf, denn in dieser Gegend wimmelt es nur so von Eisenfluträubern.", sourceObjective = "Findet Xun Xun Duftblüte in Drustvar.", completion = "Oh, Ihr wollt erfahren, wie man Winterkuss richtig pflückt? Das trifft sich ja wirklich gut... für uns beide...", sourceObjectiveStatus = "unverified-source-field" }
quests[48763] = { id = 48763, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Segen der Kälte", description = "Es ist Euch zum ersten Mal gelungen, einen Winterkuss zu pflücken, ohne dabei eines der Blütenblätter zu beschädigen.\n\nAls Ihr kurz Euer Vorgehen und die Geländemerkmale rekapituliert, fällt Euch ein Punkt auf.\n\nDie Wärme Eures Atems scheint die Blütenblätter so geschmeidig gemacht zu haben, dass sie biegsam wurden und nicht gleich brachen. Außerdem vermutet Ihr, dadurch verhindern zu können, dass die Blume ihren schützenden Kältestoß aktiviert.\n\nWenn sich diese Methodik als praktikabel erweist, könnte das extrem hilfreich sein.Ihr erlernt:", sourceObjective = "Erntet 10 Winterkuss, ohne Kälteschaden zu erleiden.", sourceObjectiveStatus = "unverified-source-field" }
quests[48764] = { id = 48764, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spitzfindiges Manöver", description = "Hey, Ihr habt doch gerade nichts zu tun, oder? Ich könnte Eure Hilfe brauchen.\n\nIch war also draußen im Sturmsangtal mit dem Abbau beschäftigt, als diese riesige, zweiköpfige Monstrosität plötzlich Jagd auf mich machte!\n\nIch bin davongerannt. Aber als ich dann in Boralus ankam, bemerkte ich, dass ich meine Lieblingsspitzhacke habe fallen lassen!\n\nIch weiß, dass das blöd klingt, aber ich wäre Euch sehr dankbar, wenn Ihr sie mir zurückbringen könntet.\n\nIhr müsst ja auch nichts Gefährliches machen. Schleicht Euch einfach an, nehmt meine Hacke und macht Euch aus dem Staub.\n\nWenn Ihr das geschafft habt, zeige ich Euch, wie Ihr Monelitflöze abbauen könnt.", sourceObjective = "Besorgt Mirtes Lieblingsspitzhacke.", progress = "Habt Ihr meine Spitzhacke wieder?", completion = "Ihr habt meine Existenz gerettet! Oder besser, meinen Existenzretter gerettet!\n\nIch hatte Euch ja einen Trick versprochen. Benutzt keine Spitzhacke, wenn Ihr bei einem Monelitflöz Erz und Fels voneinander lösen wollt.\n\nWenn das Erzstück groß genug ist, holt es einfach aus der Erde, zieht das Metall von Hand ab und entfernt so den Fels.", sourceObjectiveStatus = "unverified-source-field" }
quests[48765] = { id = 48765, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aromatische Pollen - Rang 2 freischalten", description = "Fasziniert, dass etwas so Reines weiterhin auf diesem Planeten gedeihen kann, pflückt Ihr die Pflanze. Ihr verspürt eine schwache Macht, die kurz von ihr ausgeht und dann verschwindet.\n\nAls sie in Euren Händen zerfällt, fragt Ihr Euch, ob es an diesem vom Licht verlassenen Ort wohl jemanden gibt, der weiß, wie man mit diesem wertvollen Kraut umgeht.Ihr erlernt:", sourceObjective = "Findet auf Argus jemanden, der Euch beibringen kann, wie Ihr Astralwinden ernten könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[48766] = { id = 48766, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aromatische Pollen - Rang 3 freischalten", description = "Fasziniert, dass etwas so Reines weiterhin auf diesem Planeten gedeihen kann, pflückt Ihr die Pflanze. Ihr verspürt eine schwache Macht, die kurz von ihr ausgeht und dann verschwindet.\n\nAls sie in Euren Händen zerfällt, fragt Ihr Euch, ob es an diesem vom Licht verlassenen Ort wohl jemanden gibt, der weiß, wie man mit diesem wertvollen Kraut umgeht.Ihr erlernt:", sourceObjective = "Findet auf Argus jemanden, der Euch beibringen kann, wie Ihr Astralwinden ernten könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[48767] = { id = 48767, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit erzlichen Grüßen", description = "Ihr findet eine Halskette in Form eines Ankers, auf dem der Name \"Krebeck\" in ein Banner eingraviert ist.\n\nBei dem Namen denkt Ihr sofort an Mirte Krebeck, die Bergbaulehrerin in Boralus.\n\nDer Zustand der Halskette lässt vermuten, dass sie gut gepflegt wurde. Sie möchte sie bestimmt zurückhaben.", sourceObjective = "Bringt die verlorene Halskette zurück zu Mirte Krebeck.", completion = "Beim Lichte! Ich dachte, ich hätte sie für immer verloren!\n\nSie gehörte einst meinem Urgroßvater.\n\n<Als Mirte die Halskette kurz an ihr Herz drückt, rinnt ihr eine Träne die Wange herunter. Einen Moment später sieht sie sich um und schüttelt den Kopf.>\n\nIch habe hier nichts, mit dem ich mich auch nur annähernd genug bedanken könnte. Es ist nicht viel, aber ich kann Euch zeigen, wie man aus einem Monelitflöz das meiste herausbekommt.\n\n<Über die nächsten Minuten hinweg erklärt Euch Mirte mehrere Techniken, mit denen sich die Abbaumenge aus einem Monelitflöz erhöhen lässt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[48768] = { id = 48768, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesalzene Gerechtigkeit", description = "{name}, ich habe gerade von einem Angriff auf eines unserer Schiffe erfahren, bei dem eine große Menge Sturmsilber gestohlen wurde!\n\nDieses geweihte Material kann nicht ersetzt werden. Nachdem es von einem Meerespriester geweiht wurde, wird es für ein Jahr unter Wasser gelagert!\n\nIch habe gehört, dass eine Gruppe Piraten dem Schiff gefolgt ist. Sie haben erst beobachtet, wo das Metall auf den Meeresgrund versenkt wurde, bevor sie die Mannschaft getötet und die Fracht gestohlen haben.\n\nTötet die Piraten und holt das Metall zurück.", sourceObjective = "Beschafft 100 gestohlene Sturmsilberbarren.", progress = "Verdammte Piraten!\n\nHabt Ihr die Barren besorgt?", completion = "Ah, das sind tolle Neuigkeiten! Ich lasse das gleich jemanden zu den Docks bringen.\n\nIch hatte schon befürchtet, dass sie Euch auch erwischt haben.\n\nAber Ihr habt meine Leute gerächt. Und im Gegenzug werde ich Euch in die Feinheiten der Abbautechnik von Sturmsilber einweihen.\n\n<Während der nächsten Minuten erklärt Euch Mirte, was sie über den Abbau von Sturmsilbervorkommen weiß.>", sourceObjectiveStatus = "unverified-source-field" }
quests[48769] = { id = 48769, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Andenken sammeln", description = "Es gibt da etwas, das ich niemandem sonst anvertrauen kann, und ich glaube, Ihr würdet diese Aufgabe mit dem nötigen Respekt angehen.\n\nEine alte Freundin kam heute zu mir und hatte eine verwelkte Meeresstängelblüte bei sich. Ihr Mann gehörte zur Besatzung eines Schiffs, das südöstlich von Freihafen sank. Ich weiß nicht, ob es die Piraten, die Horde oder einfach nur eine Sturmböe war, aber sie sagte, sie wolle keine Rache... Sie möchte einfach nur mit der Sache abschließen.\n\nWenn Ihr ihr ein Andenken an ihren verstorbenen Gatten bringen könntet, verrate ich Euch alles, was ich über Meeresstängel weiß... und ich wäre Euch zutiefst dankbar.", sourceObjective = "Durchsucht die mit Seetang bewachsenen Stellen, um ein Andenken an den verlorenen Seefahrer zu finden.", progress = "Habt Ihr etwas von seinem persönlichen Hab und Gut finden können?", completion = "Ich kann Euch gar nicht genug danken.\n\nDer Tod scheint dieses Land ständig heimzusuchen, doch er schmerzt nicht so sehr, wenn wir die Verstorbenen noch in unseren Erinnerungen festhalten können. Ich werde für die Beerdigung noch frisches Sternmoos brauchen, aber das werde ich selbst sammeln.\n\nÜber Meeresstängel kann ich Euch leider nicht mehr viel beibringen, aber mal sehen... Was könnte Euch weiterhelfen...? Ach ja!\n\nUm das Meiste aus jeder Pflanze herauszuholen, zieht sie vorsichtig aus dem Sand und reißt dann die Wurzeln ab, anstatt die Pflanze einfach abzuschneiden.", sourceObjectiveStatus = "unverified-source-field" }
quests[48770] = { id = 48770, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voll bis Oberkante Unterlippe", description = "He, {name}. Im Moment passt es mir nicht so gut.\n\nWenn Ihr etwas lernen möchtet, könnt Ihr mit Franko sprechen, meinem alten Lehrling. Er war mal ein richtig guter Minenarbeiter, aber jetzt ist er nur noch ein heruntergekommener Trunkenbold. Ihr findet ihn bestimmt schlafend bei den Docks.\n\nIch weiß nicht mehr, was er gerne trinkt, aber wenn Ihr ihm einfach etwas bringt, wird er es bestimmt probieren. Wenn es ihm schmeckt, wird er reden.\n\nSprecht mit Harald Atschloss, dem Schankwirt. Er verkauft eine Menge Getränke und eins davon wird Franko schon schmecken.", sourceObjective = "Bringt Franko dem Säufer ein Getränk, das er mag, damit er Euch seine Bergbaugeheimnisse verrät.", progress = "<Mirtes ehemaliger Lehrling Franko starrt Euch trunken an.>\n\nIch sag nichts... bis Ihr mir nich' was zu trink'n geholt habt.", completion = "<In wirren Worten versucht Franko, Euch die Techniken zum Abbau von Sturmsilber aus einem Flöz zu erklären.>\n\n...und so bekommt Ihr... das meiste aus einem Flöz heraus... Zzz...\n\n<Als Franko in einer penetranten Dunstwolke aus Alkohol langsam wieder in seine Traumwelt abgleitet, denkt Ihr an den Ratschlag, den er Euch gab.\n\nIhr wollt dieses neue Abbauverfahren unbedingt ausprobieren und lasst den schlafenden Mann einfach da liegen, wo er gerade ist.>", sourceObjectiveStatus = "unverified-source-field" }
quests[48771] = { id = 48771, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kräuter 07 - Selten - Rang 2 freischalten", description = "Fasziniert, dass etwas so Reines weiterhin auf diesem Planeten gedeihen kann, pflückt Ihr die Pflanze. Ihr verspürt eine schwache Macht, die kurz von ihr ausgeht und dann verschwindet.\n\nAls sie in Euren Händen zerfällt, fragt Ihr Euch, ob es an diesem vom Licht verlassenen Ort wohl jemanden gibt, der weiß, wie man mit diesem wertvollen Kraut umgeht.Ihr erlernt:", sourceObjective = "Findet auf Argus jemanden, der Euch beibringen kann, wie Ihr Astralwinden ernten könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[48772] = { id = 48772, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kräuter 07 - Selten - Rang 3 freischalten", description = "Fasziniert, dass etwas so Reines weiterhin auf diesem Planeten gedeihen kann, pflückt Ihr die Pflanze. Ihr verspürt eine schwache Macht, die kurz von ihr ausgeht und dann verschwindet.\n\nAls sie in Euren Händen zerfällt, fragt Ihr Euch, ob es an diesem vom Licht verlassenen Ort wohl jemanden gibt, der weiß, wie man mit diesem wertvollen Kraut umgeht.Ihr erlernt:", sourceObjective = "Findet auf Argus jemanden, der Euch beibringen kann, wie Ihr Astralwinden ernten könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[48773] = { id = 48773, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Papiere bitte", description = "Wenn wir Katherine keine klaren Beweise für die Verbindung zwischen Aschenwind & Co. und den Freibeutern von Freihafen liefern, war all unsere Arbeit umsonst.\n\nDie Aschenwinds mögen vorsichtig genug gewesen sein, ihre Bücher zu verschlüsseln, doch der Dockmeister hier hat keinen Grund, so vorsichtig zu sein.\n\nDurchsucht sein Büro und findet etwas, egal was, das ihn mit Aschenwind in Verbindung bringt.", sourceObjective = "Durchsucht die Aufzeichnungen des Dockmeisters.", progress = "Lady Katherine ist stur wie ein Walhai. Ohne Beweise wird sie unsere Geschichte nicht glauben.", completion = "Gute Arbeit! Das ist ein unwiderlegbarer Beweis, dass Priscilla den Piraten Waffen verkauft hat.\n\nDas ist Hochverrat!", sourceObjectiveStatus = "unverified-source-field" }
quests[48774] = { id = 48774, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schläge hören nicht auf", description = "Euch kenne ich noch nicht. Gehört Ihr zu diesen Söldnern?\n\nGibt da ein paar Kerle, die was auf die Glocke kriegen sollten.\n\n<Die grauhaarige Frau spuckt durch ein Loch, an dessen Stelle ein Vorderzahn stecken sollte.>\n\nSeit Harlan sich selbst als Admiral sieht, treiben seine Eisenflutguppies sich in der Stadt rum, als ob sie ihr Eigentum wäre. Sie zwingen andere Mannschaften, Harlan die Treue zu schwören, und verprügeln alle, die sich nicht wehren können.\n\nSicher war Freihafen zwar nie, aber zumindest war man hier frei.\n\n<Sie fährt mit ihrer Zunge über die Lücke zwischen ihren Zähnen.>\n\nMistkerle.", sourceObjective = "Tötet 5 Grobiane der Eisenfluträuber und 2 Aufseher der Eisenfluträuber.", completion = "Haha!\n\n<Gertrude spuckt wieder durch ihre Zahnlücke.>\n\nDas hatten sie verdient!", sourceObjectiveStatus = "unverified-source-field" }
quests[48776] = { id = 48776, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tauziehen", description = "Ich versuche hier meine Pause zu genießen, doch mir ist der Fusel ausgegangen.\n\nIm Wasser gleich hinter dem Dock habe ich ein wenig Grog versteckt. Ist in einer Kiste ordentlich verzurrt.\n\nTut mir den Gefallen und holt ihn her, ja? Das Tauwerk ist ganz schön verheddert, also müsst Ihr vermutlich ein wenig rumprobieren, bevor Ihr das rechte Seil erwischt.\n\nIch würde ja selbst gehen, aber wenn die mich erwischen, zwingen sie mich wieder, beim Ausladen ihrer Waffen zu helfen.", sourceObjective = "Benutzt das verhedderte Tauwerk, um an den Seebärengrog zu kommen.", progress = "Habt Ihr meinen Kram besorgt?", completion = "Ah, da haben wir ihn ja! Gut gemacht.\n\nSollen wir anstoßen?", sourceObjectiveStatus = "unverified-source-field" }
quests[48777] = { id = 48777, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Höhle der Scheusale" }
quests[48778] = { id = 48778, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steinsuppe", description = "Auf der Oberfläche des Steins findet Ihr Gravierungen, die anscheinend auf die Zutaten hindeuten.\n\nWenn Ihr die Zutaten findet, könntet Ihr die Troggsuppe selbst kochen.", sourceObjective = "Sammelt die Zutaten für Steinsuppe in der Nebelhauchkluft.", progress = "Irgendwas stimmt nicht mit dem Geschmack der Suppe. Da müssen Zutaten fehlen.", completion = "Die Suppe hat einen leicht blumigen Charakter erhalten. Sie wirkt geschmacklich ausgeglichen und ist sanft im Abgang.\n\nSie könnte sogar die köstlichste Mahlzeit sein, die Ihr je gekostet habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[48780] = { id = 48780, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gladius" }
quests[48783] = { id = 48783, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Niemand erwartet sie" }
quests[48790] = { id = 48790, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gestohlene Waren", description = "Mir wurde vor Kurzem berichtet, dass uns über Nacht 'ne Menge Versorgungsgüter abhand'n gekommen sind.\n\nIch vermute Tongos Leute hinter dem Diebstahl, aber uns fehl'n Kämpfer un' Kampfkraft, um sie anzugreif'n.\n\nIch will, dass Ihr das Versteck nach unsren Versorgungsgütern durchsucht. Wenn Ihr alles zurückbringt, was noch übrig ist, werd ich Euch für Eure Müh'n entschädig'n.\n\nWenn wir Mojambos Angriff überleb'n wollen, müss'n wir diese Versorgungsgüter so schnell wie möglich zurückbekomm'.", sourceObjective = "Bergt 6 gestohlene Versorgungsgüter.", completion = "Die von Euch gefund'nen Versorgungsgüter schein'n größtenteils unversehrt zu sein! Ihr habt unsrem Stamm 'nen großen Dienst erwies'n, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[48792] = { id = 48792, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bedrohung für die Gesellschaft", description = "Diese Troggs sind eine Bedrohung für die gesamte Gegend! Sie kommen aus ihren Höhlen, überfallen Karawanen und Lager und fressen unser Vieh. Die Kinder könnten sie mit ihrer Anwesenheit da oben aufstacheln!\n\nTötet ein paar der Troggs, bevor sie auf die Idee kommen, Ärger zu machen.", sourceObjective = "Tötet 10 Knochennagertroggs.", completion = "Ihr seht aus, als wärt Ihr in einen Kampf verwickelt worden. Haben die Troggs Bekanntschaft mit Eurer Waffe gemacht?\n\nIch hätte sie ihnen auf jeden Fall vorgestellt! Und dann, linker Haken, rechter Haken! Zack! Bumm!\n\nIch wette, die bereuen schon, sich mit Euch angelegt zu haben!", sourceObjectiveStatus = "unverified-source-field" }
quests[48793] = { id = 48793, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Abenteurerclub", description = "Dem Licht sei Dank!\n\nIch habe auf meinen Enkel und seine Freunde aufgepasst. Ich habe ihnen gesagt, sie sollen leise spielen, damit ich ein Nickerchen machen kann. Als ich wieder aufgewacht bin, habe ich nur eine Notiz gefunden, dass sie \"zu einer Expedition aufgebrochen\" sind. Sie glauben, sie finden Titanenrelikte in den Trogghöhlen!\n\nSie sind aber zu jung, um gegen Troggs zu kämpfen, und ich bin zu alt! Mein kaputtes Knie hat schon auf dem Weg hierher fast versagt.\n\nIhr seht stramm aus. Findet meinen Enkel und den Rest des \"Abenteurerclubs\" und schickt sie nach Hause!", sourceObjective = "Haltet Ausschau nach Hinweisen auf die Kinder.", progress = "Hey! Ihr habt unser Zeug gefunden!", completion = "Nils' Großvater mag ja echt nett sein, aber er hätte uns bei unsrem Streben nach Ruhm und Reichtum der Abenteurer nur aufgehalten!\n\nVielleicht hätten wir besser eine Waffe mitgenommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[48799] = { id = 48799, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treibstoff einer verdammten Welt", description = "In dieser Ödnis gibt es eine seltene und wertvolle Ressource, {name}.\n\nEinst waren Argunite auf Argus reichlich vorhanden. Ihre magischen Eigenschaften verhalfen der Zivilisation der Eredar zum Aufstieg. Diese Macht wäre bei uns viel besser aufgehoben als bei der Legion.\n\nSucht so viele makellose Argunite, wie Ihr könnt, Champion. Jedes bisschen wird uns weiterhelfen.", sourceObjective = "Sammelt 50 makellose Argunite von Invasionspunkten, seltenen Kreaturen und Schatztruhen auf Argus.", progress = "Für den Sieg brauchen wir jede Ressource, die wir aufbringen können.", completion = "Ein guter Anfang, Held. Doch wo Ihr das herhabt, gibt es noch viel mehr.", sourceObjectiveStatus = "unverified-source-field" }
quests[48800] = { id = 48800, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeichen der Fledermaus", description = "In dem Lager gibt's drei Hexen, die von Hir'eek verzauberte Talismane besitz'n.\n\nIhr müsst mir diese Talismane hol'n. Wenn das Gift dann perfekt funktioniert, könn' wir's einsetz'n.\n\nDie Essenz von Hir'eek in den Talismanen wird mein Gift derart stärk'n, dass wir es geg'n den Loa einsetz'n könn'.\n\nFalls das Gift nich' wirkt... Ach, denk'n wir lieber nich' drüber nach. Es muss einfach wirk'n. \n\nBeschafft einfach die Talismane un' ich versteck mich solang hier vor den Bluttrollen.", sourceObjective = "Holt die Talismane von den Bluthexen Vashera, Yialu und Zu'Anji in Zalamar.", progress = "Habt ihr die Talismane? Wir hab'n nich' viel Zeit, bevor Hir'eek zurückkommt un' uns verschlingt!", completion = "Ihr habt's geschafft! Muss sie einfach nur zermahl'n, so... und fertig. Hoffentlich wirkt dieses Gift, sonst geh'n wir beide drauf.", sourceObjectiveStatus = "unverified-source-field" }
quests[48801] = { id = 48801, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zalamar isolieren", description = "Hir'eek, der Loa der Fledermäuse, wurd von G'huun verderbt! Er wird uns nich' helf'n.\n\nSolange sie 'n Loa auf ihrer Seite ham, gibt's nur einen Ausweg: Wir müss'n Hir'eek töt'n.\n\nIch hab 'n total verrückt'n Plan, den wir zwei allerdings wahrscheinlich nich' überleb'n. Zuerst isolier'n wir die Siedlung.\n\nDie Kriegstrommler der Bluttrolle schlag'n Alarm, sobald hier was passiert. Sie müss'n weg... aber unauffällig.\n\nMit Eurer Tarnung fallt Ihr nich' auf. Geht einfach rüber un' kommandiert sie von ihr'n Posten ab.", sourceObjective = "Befehlt Kriegstrommler Saljo, Sheej, und Gix, ihre Posten zu verlassen.", completion = "Hah! Jetzt könn'n wir das Lager schön aufmisch'n. Die werd'n so schnell keine Verstärkung von den andren Bluttrollen bekomm'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[48803] = { id = 48803, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einen Schlüssel zur Vergangenheit schmieden", description = "Die Fragmente des Schlüssels zur Waffenkammer sind beisammen und die Dendritenformationen sollten genug Macht bieten, um den Schlüssel neu zu schmieden.\n\nDas sollte nicht lange dauern... sofern es funktioniert. Es ist schon so lange her, seit ich so etwas gemacht habe!", sourceObjective = "Werdet Zeuge, wie Gaal den Waffenkammerschlüssel neu schmiedet.", progress = "Habt einen Moment Geduld, während ich meine Arbeit beende.", completion = "Das hat funktioniert! Gut zu wissen, dass ich es noch kann.\n\nDa habt Ihr ihn, {name}. So gut wie neu.", sourceObjectiveStatus = "unverified-source-field" }
quests[48804] = { id = 48804, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alle machen Fehler", description = "Unser Traum ist es, Entdecker zu werden, also haben meine Freunde und ich den Abenteurerclub gegründet. Hier gibt es Troggs, oder? Also muss es hier auch uraltes Zeug geben!\n\nIn den Büchern steht, dass Troggs glänzende Dinge sammeln, also haben wir unser Taschengeld zusammengelegt und ihnen Gold gegeben, um ausgraben zu dürfen.\n\nLeider hat das nicht so funktioniert, wie geplant.\n\nIch konnte entkommen, aber sie haben meine Freunde. Ich habe versucht, einen Plan für ihre Befreiung zu entwickeln.\n\nKönnt Ihr helfen? Wir erwähnen Euch auch in unserem Entdeckerbericht als Ehrenmitglied!", sourceObjective = "Rettet den Abenteurerclub.", completion = "Juchhu! Ihr habt meine Freunde gerettet!\n\nWahrscheinlich wären sie auch allein entkommen, aber danke, dass Ihr die Troggs für sie abgelenkt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[48805] = { id = 48805, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forschungsrettung", description = "<Das weggeworfene Stück Papier ist eine Liste von Gegenständen, die der Abenteurerclub im Verlauf seiner \"Ausgrabungen\" hier in den Nördlichen Höhlen gefunden hat.\n\nWahrscheinlich sind keine echten Relikte dabei, aber es kann nicht schaden, die Gegenstände, die die Kinder gefunden haben, wiederzubeschaffen. Es sind immerhin zumindest schöne Souvenirs.>", sourceObjective = "Findet die \"Relikte\".", progress = "Boah! Ihr habt unsere Relikte gefunden! Tolles Zeug, oder?", completion = "Ist das nicht tolles Zeug? Wir haben echte Relikte gefunden!\n\nIch wette, Brann Bronzebart wird beeindruckt sein. Ich schreibe ihm, sobald wir zu Hause sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[48808] = { id = 48808, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dissertation", description = "Meine Dissertation!\n\nIst das zu fassen?! Diese stinkenden Troggs haben meine Dissertation an ihre Schweine verfüttert!\n\nIch habe ewig daran gesessen! Zwei ganze Tage! Wenn ich sie nicht zurückbekomme, bin ich ruiniert! Total ruiniert!\n\nKönnt Ihr es mir zurückholen?", sourceObjective = "Findet die Dissertationsseiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[48823] = { id = 48823, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knochenzerstörung", description = "Dieser Lich, Zardrax, versucht, uns auf seine Seite zu zieh'n, {name}. Ohne mich. Ich weiß, wie wir ihn aufhalt'n.\n\nDiese Skeletthaufen sin' seine Machtquelle. Wir müss'n sie verbrenn', um ihn von seiner Macht abzuschneid'n.\n\nMein Feuermojo is' stark. Ich kann 'n Teil meiner Verbindung zum Feuer auf Euch übertrag'n, damit Ihr die Skeletthaufen verbrenn' könnt.\n\nIch bleib mit Kal'dran hier. Er muss von Zardrax ferngehalt'n werd'n.", sourceObjective = "Zerstört 3 Skeletthaufen mit Da'juls Feuermojo.", progress = "Los. Zerstört endlich diese Skeletthaufen.", completion = "Die Feuer konnt man bis hierher seh'n. Das hat Zardrax sicher wehgetan.", sourceObjectiveStatus = "unverified-source-field" }
quests[48825] = { id = 48825, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Macht verweigert", description = "Ah! Oh, Ihr seid's, {name}. Zardrax hatte mich fast überzeugt, dass alle Hoffnung verlor'n is'.\n\nIch hatte mal 'nen Plan geschmiedet, ihn aufzuhalt'n. Wir hätt'n nur seine Gehilfin, Verhexerin Nana'kwug, umbring'n un' ihr den Blutfetisch entreiß'n müss'n. Damit hilft die Zardrax nämlich, seine Macht auszuweit'n.\n\nMit dem Fetisch un' seinem Voodoo kann Da'jul uns dann 'ne Menge Macht verleih'n.\n\nDafür is' aber jetzt zu spät. Wir sollt'n uns einfach Zardrax füg'n. Er is' einfach zu stark.", sourceObjective = "Besiegt Verhexerin Nana'kwug und nehmt ihren Blutfetisch an Euch.", progress = "Habt Ihr den Fetisch schon? Vielleicht beruhigt sich Kal'dran, wenn er sieht, dass wir 'ne Chance hab'n.", completion = "Gut, dass Ihr den Fetisch besorgt habt. Damit kann ich 'ne Menge anstell'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[48827] = { id = 48827, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Varga" }
