quests[48837] = { id = 48837, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Allseher Xanarian" }
quests[48840] = { id = 48840, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruinöse Werbung", description = "Jetz', wo der Goldhauer startklar für Betrieb is', müss'n wir sicherstell'n, dass auch jeder in Vol'dun davon Wind bekommt!\n\nAm besten, wir fang'n bei den Karawanenwagen der Vulpera an. Die ham nich' mal eigene vier Wände!\n\nIm Norden bei den Ruinen hab ich vor einiger Zeit 'n Rudel Vulpera geseh'n. Die hatt'n fast nix.\n\nBringt ihnen den Gutschein hier mit und sagt ihnen, dass die erste Übernachtung nix kostet.", sourceObjective = "Liefert den Gutschein für den Goldhauer bei Kenzou ab.\n\nBereitgestellter Gegenstand:", completion = "<Kenzou beäugt skeptisch das Papier, das Ihr ihm gegeben habt.>\n\nNein, da werde ich nicht hingehen. Aber Ihr, seid Ihr auf der Suche nach echter Arbeit?", sourceObjectiveStatus = "unverified-source-field" }
quests[48846] = { id = 48846, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flüssige Motivation", description = "<Zauljin bedeutet Euch, näher zu kommen. Er ist eindeutig betrunken.>\n\nIch hab Information'n über Mojambo...<hicks!>...Wie viel wär'n sie Euch wert?\n\nIhr... <hicks!>... glaubt mir nich'? Niemand achtet auf 'nen Betrunkenen. Ich hör alle möglich'n Dinge...\n\nWas habt Ihr schon zu verlier'n? Alles, was es Euch kost'n würde, wäre 'ne Flasche...<hicks!>...Edler Zanchulitropfen!\n\nWas sagt Ihr, Mann?", sourceObjective = "Bringt eine Flasche vom edlen Zanchulitropfen zu Zauljin.", completion = "Mojambo verbündet sich mit 'ner Bande von außerhalb, um uns anzugreif'n? Es mag ihm ums Geschäft geh'n, aber dass er so weit geh'n würde, hätt ich nich' gedacht. Wir brauch'n so schnell wie möglich 'nen Plan...", sourceObjectiveStatus = "unverified-source-field" }
quests[48847] = { id = 48847, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stammesbewaffnung", description = "Wir ham gesehen, dass ein paar Leute von Tongos Bande die Gegend ausgespäht ham, während Ihr weg wart. Das is' vielleicht die Ruhe vor dem Sturm.\n\nWir müss'n die Waffen, die Ihr aus Tongos Unterschlupf mitgebracht habt, an die andren Ausgestoßenen verteil'n. Mojambos Bande könnt jetzt jederzeit angreif'n.\n\nWir müss'n vorbereitet sein. Nehmt die Waffen un' bringt sie den unbewaffneten Stammesmitgliedern.\n\nWenn Mojambo glaubt, dass er unser Zuhause ohne Gegenwehr einnehm'n kann, wird er sich wundern.", sourceObjective = "Bewaffnet 8 Glutsandausgestoßene.", completion = "Gut, dass Ihr den Stamm bewaffnet habt! Mojambo un' seine Bande greif'n uns in dies'm Aug'nblick an!", sourceObjectiveStatus = "unverified-source-field" }
quests[48850] = { id = 48850, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tongo", description = "Wenn Mojambo die Bande von Tongo als Verstärkung angeheuert hat, ham wir noch mehr Probleme, als wir gedacht ham.\n\nTongo is'n grausamer un' sadistischer Plünderer, der seine Opfer gerne leid'n sieht. Seine Bande is' dafür bekannt, ihre Opfer zu foltern.\n\nWir könn' uns unmöglich geg'n beide Band'n verteidig'n. Wir ham nur 'ne Chance, wenn wir zuerst angreif'n.\n\nWenn Ihr Tongo noch vor dem Angriff ausschaltet, wird Mojambo auf Unterstützung wart'n, die nie kommt. Vielleicht könn' wir das zu unsrem Vorteil nutz'n...", sourceObjective = "Holt Euch Tongos Kopf.", progress = "Is' Tongo besiegt?", completion = "Jetzt wo Tongo weg is', müss'n wir nur noch mit Mojambo fertigwerd'n...", sourceObjectiveStatus = "unverified-source-field" }
quests[48852] = { id = 48852, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zardrax aufhalten" }
quests[48853] = { id = 48853, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abschlussarbeit", description = "Alle da, außer Nils.\n\nEr ist in der großen Höhle! Er hat wohl nach Relikten gesucht, aber jetzt ist er da gefangen!\n\nKönnt Ihr ihn auch retten?", sourceObjective = "Tötet Krack den Felsenrüttler und befreit Nils Risswalt.", completion = "Danke, dass Ihr meinen Enkel und seine Freunde gerettet habt.\n\nSie werden sicher zu großen Entdeckern heranwachsen.\n\nBis es so weit ist, haben sie aber erst einmal Hausarrest!", sourceObjectiveStatus = "unverified-source-field" }
quests[48854] = { id = 48854, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Machtköder", description = "Ah... <'n/'ne:c> {class}. Ihr seid dann wohl {name}... hab die Leute über Euch flüstern hör'n. Vielleicht seid Ihr ja schlauer als diese beid'n.\n\nDie Bluttrolle werd'n Zuldazar einnehm'n, das is' sicher.\n\nVersprecht, mir zu dien'n, und ich verschon Euch. Ich mach Euch mächtiger, als Ihr je zu träum'n gewagt habt.\n\nHört Euch mein Angebot an...", sourceObjective = "Hört Euch Zardrax' Ansprache an.", completion = "Zardrax wird versuch'n, uns auf seine Seite zu zieh'n, aber das wird ihm nich' geling'n. Wir mach'n diesem Lich und allen, die den Bluttrollen helf'n, ein Ende!", sourceObjectiveStatus = "unverified-source-field" }
quests[48855] = { id = 48855, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demütigen der Schrecken", description = "Als wir hier ankam'n, hab ich auf der andren Seite von Zardrax' Grabhügel 'n Riesenproblem entdeckt.\n\nDie Gegend dort wimmelt von monströs'n Zombies. Sie dürf'n Zuldazar nich' erreichen.\n\nIch hab den Fetisch, den Ihr gefund'n habt, mit meinem Voodoo modifiziert. Verwendet ihn, um die Zombies zu schwäch'n und zu töt'n.", sourceObjective = "Besiegt 3 rekonstruierte Schrecken, indem Ihr sie mit dem modifizierten Blutfetisch schwächt.", completion = "Gute Arbeit. Die Leute in Zuldazar müss'n jetzt keine Angst mehr vor diesen Zombies hab'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[48856] = { id = 48856, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kanalisierung kappen", description = "Diese Skelette lass'n Blutmagie in Zardrax' Grabhügel ström'n. Ich schätz, Zardrax hat sie erschaff'n, um seine Macht weiter zu stärk'n.\n\nWir müss'n die Skelette beseitig'n, wenn wir 'ne Chance ham woll'n, den Lich zu töt'n. Wenn er sie als Machtquelle verliert, sollt er schwächer werd'n.\n\nIch werd Euch hier den Rücken freihalt'n. Wer weiß, ob die Bluttrolle zurückkomm' und angreif'n.", sourceObjective = "Besiegt 8 Kanalisierer von Zardrax.", completion = "Ich riech förmlich, wie Zardrax' Macht schwindet. Wir steh'n kurz davor, diese Sache zu beend'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[48857] = { id = 48857, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Hoffnung mehr", description = "Ich mach da nich' mehr mit! Ihr un' Da'jul liegt FALSCH! Wir könn' Zardrax nich' stopp'n!\n\nIch geh jetzt un' keiner hält mich auf. Zardrax wird uns vor der Vernichtung bewahr'n! Er macht uns wieder stark!", sourceObjective = "Beruhigt Kal'dran.", completion = "Wir hab'n keine Zeit, um Kal'dran zu trauern. Er hat sich entschied'n, genauso wie wir uns jetzt entscheid'n un' Zardrax töt'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[48864] = { id = 48864, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der zerschlagene Schmied", description = "{class}, ich glaube, dass es sich dabei um ein Stück des Schlüssels zur Waffenkammer des Triumvirats handeln könnte. Wir haben sie vor unserer Flucht von Argus hinter uns verschlossen. Atalaa, meine Stellvertreterin, führte eine Streitkraft an, um die Kammer zu sichern. Das ist nun schon so lange her...\n\nIch bin mir nicht mehr sicher, doch es gibt noch jemanden, der es genau wissen sollte. Der Schmied des Schlüssels hieß Gaal. Da in Krokuun noch Zerschlagene leben, könnte auch er noch am Leben sein.", sourceObjective = "Findet den Schmied Gaal.\n\nBereitgestellter Gegenstand:", completion = "Es freut mich, zu hören, dass es Fareeya gut geht.\n\nSie hat recht... dies ist das Fragment des Schlüssels zur Waffenkammer, den ich vor so langer Zeit für sie geschmiedet habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[48866] = { id = 48866, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leerenwächterin Valsuran" }
quests[48867] = { id = 48867, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oberster Alchemist Munculus" }
quests[48869] = { id = 48869, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ärger-Licher Zahltag", description = "Wir dürf'n uns nich' auf den Verlust von Kal'dran konzentrier'n. Er hat die Hoffnung aufgegeb'n. Wir werd'n das nicht.\n\nZardrax is' geschwächt, deshalb müss'n wir jetzt zuschlag'n.\n\nGeht tief in seinen Grabhügel un' vernichtet ihn, ein für alle Mal. Das wird dies'n Bluttrollen Respekt beibring'n!\n\nIch kann Euch leider nich' helf'n. Ich bin vom letzt'n Kampf mit den Trollen, als Ihr nich' da wart, noch zu geschwächt.\n\nKümmert Euch nich' um mich, mit dem Ungeziefer werd ich schon fertig, wenn's zurückkommt.", sourceObjective = "Besiegt Zardrax den Ermächtiger.", progress = "Zardrax muss sterb'n. Jetzt oder nie!", completion = "Ihr habt's geschafft! Zardrax is' weg un' die Bluttrolle hab'n jetzt 'ne wichtige Machtquelle verlor'n.\n\nIch mach mich jetzt zurück zum Lager un' bericht Prinzessin Talanji von Kal'dran.\n\nSie muss erfahr'n, dass er den Glauben an unsre Sache verlor'n hat... Vielleicht gibt's da noch andre, die seiner Meinung sin'.", sourceObjectiveStatus = "unverified-source-field" }
quests[48871] = { id = 48871, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relikte retten", description = "Den Informationen zufolge, die Ihr uns gebracht habt, sollten wir diese Relikte unserer Sammlung hinzufügen.\n\nUntersucht die Ruinen und seht, ob Ihr diese \"Liebesbeweise\" finden könnt, die die Sethrak vielleicht ihren Hütern hinterlassen haben.\n\nEs ist besser, wir finden Hände, die sie in Ehren halten, als Hände, die sie zerstören.\n\nAußerdem gewinnt im Laufe der Zeit alles an Interesse... für die richtigen Leute.", sourceObjective = "Sammelt 8 Ahjanirelikte in Zul'Ahjin.", progress = "Habt Ihr die Relikte gefunden?", completion = "Perfekt. Die Macht der Nostalgie ist faszinierend. Diese Relikte werden großen sentimentalen Wert haben. Der Geldwert dürfte auch nicht übel sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[48872] = { id = 48872, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ausgrabung beschleunigen", description = "Ganz gleich, wo wir hinkommen, sie sind schon da. Sethrak. Und es sind nie die, die man sehen will.\n\nAnscheinend suchen sie alle nach irgendeinem Schlüssel. Gemäß dieser neuen Information glaube ich nicht, dass sie am richtigen Ort suchen.\n\nEhrlich, so unterhaltsam es sein mag, sie an der Nase herumzuführen, wir müssen unsere Arbeit hier zu Ende bringen und weiterziehen.\n\nWenn Ihr einige von ihnen loswerden könntet, wäre das unserer Mannschaft eine große Hilfe!", sourceObjective = "Tötet 12 Sethrak in den Ruinen.", completion = "Gut gemacht! Sie müssen so genervt sein. Das macht großen Spaß!", sourceObjectiveStatus = "unverified-source-field" }
